head.script:
//
/* Apply saved / preferred color theme before first paint (prevents flash) */
try{var __t=localStorage.getItem('th');if(!__t&&window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches){__t='dark';}if(__t){document.documentElement.setAttribute('data-theme',__t);}}catch(e){}
//

head.b:skin:
/* ================================================================
   THEME VARIABLES - change the colors of the whole site here
   ================================================================ */
:root{
  --brand:#2563EB;      /* primary blue  */
  --brand-d:#1D4ED8;    /* hover blue    */
  --accent:#14B8A6;     /* teal accent   */
  --navy:#0F172A;       /* header/footer */
  --navy2:#1E293B;
  --bg:#F8FAFC;         /* page background */
  --card:#FFFFFF;
  --text:#0F172A;
  --muted:#475569;
  --line:#E2E8F0;
  --soft:#EFF6FF;
  --link:#1D4ED8;
  --ok:#15803D; --warn:#B45309; --err:#DC2626;
  --r:14px;
  --sh:0 1px 2px rgba(15,23,42,.06),0 10px 30px rgba(15,23,42,.07);
  --font:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial,'Noto Sans',sans-serif;
  --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace;
}
html[data-theme='dark']{
  --bg:#0B1220; --card:#111B2F; --text:#E6ECF5; --muted:#A3B1C6; --line:#24324D; --soft:#15233F; --link:#7DB1FF;
  --sh:0 1px 2px rgba(0,0,0,.4),0 10px 30px rgba(0,0,0,.35);
}

/* ---------- Base ---------- */
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.65 var(--font);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{margin:0 0 .5em;line-height:1.2;letter-spacing:-.02em;color:var(--text)}
h1{font-size:clamp(1.9rem,4.4vw,3rem);font-weight:800}
h2{font-size:clamp(1.4rem,2.6vw,1.9rem);font-weight:700}
h3{font-size:1.1rem;font-weight:650}
p{margin:0 0 1em}
a{color:var(--link);text-decoration:none}
a:hover{text-decoration:underline}
img,svg,canvas{max-width:100%}
img{height:auto}
button,input,select,textarea{font:inherit;color:inherit}
[hidden]{display:none !important}
.container{width:100%;max-width:1200px;margin:0 auto;padding:0 20px}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.skip{position:absolute;left:12px;top:-60px;background:var(--brand);color:#fff;padding:10px 16px;border-radius:8px;z-index:1000}
.skip:focus{top:12px;text-decoration:none}
:focus-visible{outline:3px solid #60A5FA;outline-offset:2px;border-radius:6px}
.section{margin:0}.widget{margin:0}
.ico{width:1.25em;height:1.25em;flex:none;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

/* ---------- Header ---------- */
.site-header{position:sticky;top:0;z-index:100;background:var(--navy);color:#E2E8F0;border-bottom:1px solid rgba(255,255,255,.08);padding-top:env(safe-area-inset-top,0)}
.hdr{display:flex;align-items:center;gap:20px;min-height:64px}
.brand{display:flex;align-items:center;gap:10px;color:#fff;font-weight:800;font-size:1.15rem;letter-spacing:-.02em}
.brand:hover{text-decoration:none}
.brand-mark{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:linear-gradient(135deg,var(--brand),var(--accent));color:#fff}
.brand-mark svg{width:20px;height:20px;stroke:#fff;fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.nav{display:flex;gap:4px;margin-left:8px}
.nav a{color:#CBD5E1;padding:8px 12px;border-radius:8px;font-weight:500;font-size:.95rem}
.nav a:hover,.nav a.on{color:#fff;background:rgba(255,255,255,.09);text-decoration:none}
.hdr-actions{display:flex;align-items:center;gap:8px;margin-left:auto}
.hdr-search{position:relative}
.hdr-search input{width:220px;padding:9px 12px 9px 36px;border-radius:10px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.07);color:#fff;transition:width .2s,background .2s}
.hdr-search input::placeholder{color:#94A3B8}
.hdr-search input:focus{width:280px;background:rgba(255,255,255,.12);outline-color:#60A5FA}
.hdr-search .ico{position:absolute;left:11px;top:50%;transform:translateY(-50%);color:#94A3B8;width:16px;height:16px;pointer-events:none}
.hs-res{position:absolute;right:0;top:calc(100% + 8px);width:340px;max-width:calc(100vw - 32px);margin:0;padding:6px;list-style:none;background:var(--card);color:var(--text);border:1px solid var(--line);border-radius:12px;box-shadow:var(--sh)}
.hs-res li a{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:8px;color:var(--text)}
.hs-res li a:hover,.hs-res li a.sel{background:var(--soft);text-decoration:none}
.hs-res .ico{color:var(--brand)}
.hs-res small{color:var(--muted);display:block;line-height:1.3}
.hs-empty{padding:10px;color:var(--muted);font-size:.9rem}
.icon-btn{display:grid;place-items:center;width:40px;height:40px;border-radius:10px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.07);color:#E2E8F0;cursor:pointer;transition:background .2s}
.icon-btn:hover{background:rgba(255,255,255,.16)}
.menu-btn{display:none}

/* ---------- Buttons & form controls ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 18px;border-radius:10px;border:1px solid var(--line);background:var(--card);color:var(--text);font-weight:600;font-size:.95rem;cursor:pointer;transition:transform .12s,background .2s,border-color .2s,box-shadow .2s;text-decoration:none;line-height:1.2}
.btn:hover{border-color:var(--brand);text-decoration:none}
.btn:active{transform:translateY(1px)}
.btn-primary{background:var(--brand);border-color:var(--brand);color:#fff}
.btn-primary:hover{background:var(--brand-d);border-color:var(--brand-d)}
.btn-teal{background:var(--accent);border-color:var(--accent);color:#042F2E}
.btn-teal:hover{filter:brightness(.94);border-color:var(--accent)}
.btn-sm{padding:7px 12px;font-size:.85rem;border-radius:8px}
.btn[disabled]{opacity:.5;cursor:not-allowed}
.btn-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:14px;min-width:0}
.field>label,.lbl{font-weight:600;font-size:.9rem}
.hint{color:var(--muted);font-size:.85rem}
input[type=text],input[type=number],input[type=date],input[type=search],input[type=email],input[type=url],select,textarea{width:100%;padding:11px 13px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--text);transition:border-color .2s,box-shadow .2s}
input:focus,select:focus,textarea:focus{border-color:var(--brand);box-shadow:0 0 0 3px rgba(37,99,235,.22);outline:none}
textarea{min-height:170px;resize:vertical;line-height:1.55}
textarea.mono,.mono{font-family:var(--mono);font-size:.9rem}
input[type=range]{width:100%;accent-color:var(--brand)}
input[type=color]{width:56px;height:44px;padding:3px;border:1px solid var(--line);border-radius:10px;background:var(--card);cursor:pointer}
.chk{display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:500;font-size:.95rem}
.chk input{width:18px;height:18px;accent-color:var(--brand)}
.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.row{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap}
.row>*{flex:1 1 140px}
.tabs{display:inline-flex;gap:4px;padding:4px;background:var(--soft);border-radius:12px;margin-bottom:16px;flex-wrap:wrap}
.tabs button{border:0;background:transparent;padding:8px 16px;border-radius:9px;font-weight:600;cursor:pointer;color:var(--muted)}
.tabs button[aria-selected=true]{background:var(--card);color:var(--brand);box-shadow:0 1px 3px rgba(15,23,42,.15)}
html[data-theme='dark'] .tabs button[aria-selected=true]{color:#93C5FD}
.msg{padding:11px 14px;border-radius:10px;font-size:.92rem;margin:12px 0 0;border:1px solid}
.msg.err{background:#FEF2F2;border-color:#FECACA;color:#991B1B}
.msg.ok{background:#F0FDF4;border-color:#BBF7D0;color:#166534}
html[data-theme='dark'] .msg.err{background:#3B1216;border-color:#7F1D1D;color:#FECACA}
html[data-theme='dark'] .msg.ok{background:#0F2A1A;border-color:#14532D;color:#BBF7D0}

/* ---------- Hero ---------- */
.hero{background:radial-gradient(900px 380px at 82% -10%,rgba(20,184,166,.28),transparent 60%),radial-gradient(800px 420px at 8% 0,rgba(37,99,235,.42),transparent 60%),var(--navy);color:#E2E8F0;padding:72px 0 64px}
.hero-in{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:48px;align-items:center}
.hero h1{color:#fff;margin-bottom:16px}
.hero p.lead{font-size:1.15rem;color:#CBD5E1;max-width:34em}
.hero-search{position:relative;margin:26px 0 14px;max-width:560px}
.hero-search input{padding:16px 18px 16px 50px;font-size:1.05rem;border-radius:14px;border:1px solid rgba(255,255,255,.2);background:#fff;color:#0F172A;box-shadow:0 12px 32px rgba(0,0,0,.28)}
.hero-search .ico{position:absolute;left:18px;top:50%;transform:translateY(-50%);color:#64748B;width:20px;height:20px}
.quick{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:.9rem;color:#94A3B8}
.quick a{color:#E2E8F0;padding:5px 11px;border:1px solid rgba(255,255,255,.18);border-radius:999px;font-size:.85rem}
.quick a:hover{background:rgba(255,255,255,.1);text-decoration:none}
.hero-card{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:18px;padding:22px;backdrop-filter:blur(6px)}
.hero-card h2{color:#fff;font-size:1.05rem;margin-bottom:14px}
.hc-row{display:flex;align-items:center;gap:12px;padding:11px 0;border-top:1px solid rgba(255,255,255,.1);color:#E2E8F0}
.hc-row:first-of-type{border-top:0}
.hc-row .ico{color:var(--accent);width:22px;height:22px}
.hc-row b{display:block;color:#fff;font-weight:650}
.hc-row span{font-size:.88rem;color:#94A3B8}

/* ---------- Sections ---------- */
.sec{padding:64px 0}
.sec.alt{background:var(--card);border-block:1px solid var(--line)}
.sec-head{max-width:640px;margin-bottom:28px}
.sec-head p{color:var(--muted)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 24px}
.chip{padding:8px 16px;border-radius:999px;border:1px solid var(--line);background:var(--card);font-weight:600;font-size:.9rem;cursor:pointer;color:var(--muted);transition:all .2s}
.chip:hover{border-color:var(--brand);color:var(--brand)}
.chip[aria-pressed=true]{background:var(--brand);border-color:var(--brand);color:#fff}
.tool-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:18px}
.tool-card{display:flex;flex-direction:column;gap:10px;padding:22px;background:var(--card);border:1px solid var(--line);border-radius:var(--r);color:var(--text);box-shadow:var(--sh);transition:transform .2s,border-color .2s,box-shadow .2s}
.tool-card:hover{transform:translateY(-4px);border-color:var(--brand);text-decoration:none;box-shadow:0 14px 34px rgba(37,99,235,.16)}
.tc-ico{display:grid;place-items:center;width:46px;height:46px;border-radius:12px;background:var(--soft);color:var(--brand)}
.tc-ico .ico{width:24px;height:24px}
.tool-card h3{margin:0}
.tool-card p{margin:0;color:var(--muted);font-size:.93rem;flex:1}
.tc-cat{font-size:.8rem;color:var(--muted);font-weight:600}
.empty{padding:40px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:var(--r)}
.why-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:26px 32px}
.why{display:flex;gap:14px}
.why .tc-ico{background:rgba(20,184,166,.14);color:#0F766E;flex:none}
html[data-theme='dark'] .why .tc-ico{color:#5EEAD4}
.why h3{margin-bottom:4px}
.why p{margin:0;color:var(--muted);font-size:.95rem}
.faq details{background:var(--card);border:1px solid var(--line);border-radius:12px;margin-bottom:10px;padding:0 18px}
.faq summary{cursor:pointer;padding:16px 26px 16px 0;font-weight:650;list-style:none;position:relative}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:'+';position:absolute;right:0;top:50%;transform:translateY(-50%);font-size:1.4rem;color:var(--brand);transition:transform .2s}
.faq details[open] summary::after{transform:translateY(-50%) rotate(45deg)}
.faq details p{color:var(--muted);padding-bottom:6px}
.updated{color:var(--muted);font-size:.88rem;margin-top:22px}

/* ---------- Tool / page view ---------- */
.crumb{padding:18px 0 4px;font-size:.88rem;color:var(--muted)}
.crumb ol{display:flex;flex-wrap:wrap;gap:6px;list-style:none;margin:0;padding:0}
.crumb li+li::before{content:'/';margin-right:6px;color:var(--line)}
.crumb a{color:var(--muted)}
.tool-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:32px;padding:14px 0 56px;align-items:start}
.tool-head{display:flex;gap:16px;align-items:flex-start;margin-bottom:20px}
.tool-head .tc-ico{width:56px;height:56px;border-radius:14px}
.tool-head h1{font-size:clamp(1.6rem,3.2vw,2.3rem);margin-bottom:6px}
.tool-head p{margin:0;color:var(--muted)}
.trust{display:inline-flex;align-items:center;gap:6px;margin-top:10px;padding:5px 12px;border-radius:999px;background:rgba(20,184,166,.14);color:#0F766E;font-size:.82rem;font-weight:600}
html[data-theme='dark'] .trust{color:#5EEAD4}
.trust .ico{width:14px;height:14px}
.tool-box{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:24px;box-shadow:var(--sh)}
.article{margin-top:34px;background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:28px 30px}
.article h2{margin-top:1.4em;font-size:1.4rem}
.article h2:first-child{margin-top:0}
.article h3{margin-top:1.1em;font-size:1.05rem}
.article p,.article li{color:var(--muted)}
.article ol,.article ul{padding-left:1.3em;margin:0 0 1em}
.article li{margin-bottom:.4em}
.article li strong,.article p strong{color:var(--text)}
.side{position:sticky;top:84px;display:flex;flex-direction:column;gap:18px}
.side-box{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:18px;box-shadow:var(--sh)}
.side-box h2{font-size:1rem;margin-bottom:10px}
.rel{display:flex;gap:10px;align-items:center;padding:9px;border-radius:10px;color:var(--text)}
.rel:hover{background:var(--soft);text-decoration:none}
.rel .tc-ico{width:36px;height:36px;border-radius:9px}
.rel .tc-ico .ico{width:18px;height:18px}
.rel small{display:block;color:var(--muted);line-height:1.3}
.legal h1{font-size:clamp(1.7rem,3.4vw,2.4rem)}
.legal .article{margin-top:14px}

/* ---------- Stats / output blocks ---------- */
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin:18px 0}
.stat{background:var(--soft);border-radius:12px;padding:14px 16px}
.stat b{display:block;font-size:1.6rem;line-height:1.15;font-weight:800;letter-spacing:-.02em;color:var(--text)}
.stat span{font-size:.82rem;color:var(--muted);font-weight:500}
.outbox{display:flex;align-items:center;gap:10px;background:var(--soft);border:1px solid var(--line);border-radius:12px;padding:10px 12px}
.outbox input{background:transparent;border:0;padding:6px;font-family:var(--mono);font-size:1.05rem;box-shadow:none !important}
.meter{height:10px;border-radius:99px;background:var(--line);overflow:hidden;margin:10px 0 6px}
.meter i{display:block;height:100%;width:0;border-radius:99px;transition:width .25s,background .25s}
.tbl{width:100%;border-collapse:collapse;font-size:.92rem}
.tbl th,.tbl td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line)}
.tbl th{color:var(--muted);font-weight:600;font-size:.82rem}
.bar{display:block;height:6px;border-radius:9px;background:var(--brand);min-width:2px}
.drop{border:2px dashed var(--line);border-radius:var(--r);padding:36px 20px;text-align:center;cursor:pointer;transition:border-color .2s,background .2s;color:var(--muted)}
.drop:hover,.drop.over{border-color:var(--brand);background:var(--soft)}
.drop .ico{width:38px;height:38px;color:var(--brand);margin-bottom:8px}
.cmp{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:18px}
.cmp figure{margin:0;background:var(--soft);border-radius:12px;padding:12px;text-align:center}
.cmp img{max-height:260px;border-radius:8px;object-fit:contain;background:repeating-conic-gradient(#0001 0 25%,#0000 0 50%) 0 0/16px 16px}
.cmp figcaption{margin-top:8px;font-weight:600;font-size:.9rem}
.cmp figcaption span{color:var(--muted);font-weight:500}
.scale{position:relative;height:14px;border-radius:99px;background:linear-gradient(90deg,#3B82F6 0 18.5%,#22C55E 18.5% 45%,#F59E0B 45% 70%,#EF4444 70% 100%);margin:22px 0 8px}
.scale i{position:absolute;top:-6px;width:4px;height:26px;background:var(--text);border-radius:3px;transform:translateX(-50%);transition:left .3s}
.big{font-size:clamp(2.4rem,7vw,3.6rem);font-weight:800;letter-spacing:-.03em;line-height:1}
.pill{display:inline-block;padding:5px 14px;border-radius:99px;font-weight:700;font-size:.9rem;color:#fff}
.swatch{height:120px;border-radius:14px;border:1px solid var(--line);margin-bottom:14px;transition:background .15s}
.palette{display:flex;flex-wrap:wrap;gap:6px}
.palette button{width:44px;height:44px;border-radius:10px;border:1px solid rgba(0,0,0,.12);cursor:pointer;padding:0}
.palette button:hover{transform:scale(1.08)}
.vrow{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}
.vrow code{flex:1;font-family:var(--mono);font-size:.92rem;word-break:break-all}
.vrow b{width:52px;font-size:.82rem;color:var(--muted)}
.qr-out{display:flex;flex-direction:column;align-items:center;gap:14px;padding:18px;background:var(--soft);border-radius:14px}
.qr-out canvas{background:#fff;border-radius:8px;image-rendering:pixelated;max-width:100%;height:auto}
.case-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:8px;margin:14px 0}
.case-grid .btn[aria-pressed=true]{background:var(--brand);border-color:var(--brand);color:#fff}
.flist{margin:14px 0 4px}
.frow{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--card);margin-bottom:8px}
.frow .ico{color:var(--brand);flex:none;width:20px;height:20px}
.frow .fname{flex:1;font-weight:600;font-size:.92rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.frow .fsize{color:var(--muted);font-size:.85rem;flex:none}
.frow .fbtns{display:flex;gap:4px;flex:none}
.frow .fbtns button{width:32px;height:32px;border-radius:8px;border:1px solid var(--line);background:var(--soft);color:var(--text);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;padding:0;font-size:.95rem;line-height:1}
.frow .fbtns button:hover{border-color:var(--brand)}
.frow .fbtns button:disabled{opacity:.35;cursor:not-allowed}
.frow .fbtns .ico{width:15px;height:15px;color:inherit}
.crop-wrap{position:relative;display:inline-block;max-width:100%;margin:14px 0;touch-action:none;border-radius:10px;overflow:hidden;background:var(--soft)}
.crop-wrap img{display:block;max-width:100%;height:auto;-webkit-user-drag:none;user-select:none;pointer-events:none}
.crop-box{position:absolute;border:2px solid var(--brand);box-shadow:0 0 0 9999px rgba(15,23,42,.5);cursor:move;touch-action:none;min-width:20px;min-height:20px}
html[data-theme='dark'] .crop-box{box-shadow:0 0 0 9999px rgba(0,0,0,.65)}

/* ---------- Blog area (posts, label & search pages, 404) ---------- */
.blog-wrap{padding:44px 20px 56px}
.blog-posts{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:22px}
.blog-posts.item,.blog-posts.static_page{display:block;max-width:820px;margin:0 auto}
.archive-title{font-size:clamp(1.5rem,3vw,2.2rem);margin-bottom:24px}
.post-card{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh);transition:transform .2s,border-color .2s}
.post-card:hover{transform:translateY(-3px);border-color:var(--brand)}
.pc-img{display:block;aspect-ratio:16/9;background:var(--soft);overflow:hidden}
.pc-img img{width:100%;height:100%;object-fit:cover;display:block}
.pc-body{padding:18px 20px 20px;display:flex;flex-direction:column;flex:1}
.pc-date{font-size:.82rem;color:var(--muted);margin-bottom:6px}
.pc-body h2{font-size:1.15rem;margin-bottom:8px}
.pc-body h2 a{color:var(--text)}
.pc-body p{color:var(--muted);font-size:.93rem;flex:1}
.pc-more{font-weight:600;font-size:.92rem}
.post.full{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:clamp(20px,4vw,40px);box-shadow:var(--sh)}
.post.full h1{font-size:clamp(1.7rem,4vw,2.5rem)}
.post-meta{display:flex;flex-wrap:wrap;gap:6px 14px;color:var(--muted);font-size:.9rem;margin-bottom:22px}
.post-body{font-size:1.06rem;line-height:1.8;overflow-wrap:anywhere}
.post-body img{max-width:100%;height:auto;border-radius:10px}
.post-body h2,.post-body h3{margin-top:1.6em}
.post-body a{text-decoration:underline}
.post-body table{border-collapse:collapse;max-width:100%;display:block;overflow-x:auto}
.post-body th,.post-body td{border:1px solid var(--line);padding:8px 12px}
.post-body pre{background:var(--navy);color:#E2E8F0;padding:16px;border-radius:10px;overflow:auto}
.post-body blockquote{margin:1.2em 0;padding:4px 18px;border-left:4px solid var(--accent);color:var(--muted)}
.labels a{display:inline-block;padding:3px 11px;border-radius:99px;background:var(--soft);font-size:.82rem;margin:0 6px 6px 0;color:var(--link)}
.share{display:flex;flex-wrap:wrap;gap:8px;margin-top:26px;padding-top:18px;border-top:1px solid var(--line);align-items:center}
.pager{display:flex;justify-content:space-between;gap:12px;margin-top:28px;grid-column:1/-1}
.pager a{padding:10px 18px;border:1px solid var(--line);border-radius:10px;background:var(--card);font-weight:600}
.err-box{text-align:center;padding:70px 20px;max-width:560px;margin:0 auto}
.err-box .big{color:var(--brand);margin-bottom:12px}
.m-home .archive-title,.m-home .pager{display:none}
.m-home .blog-posts .post-card:nth-child(n+7){display:none}
.m-home .blog-wrap{padding:0}
.more-link{margin-top:22px}

/* ---------- Ads (hidden until enabled) ---------- */
.ad-slot{margin:22px auto;max-width:1200px;padding:0 20px;text-align:center}
.ad-slot.in-side{padding:0;margin:0}
.ad-label{display:block;font-size:.72rem;color:var(--muted);margin-bottom:4px}
.ad-inner{min-height:90px;overflow:hidden}

/* ---------- Footer ---------- */
.site-footer{background:var(--navy);color:#CBD5E1;margin-top:0;padding:56px 0 24px}
.foot-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:36px;margin-bottom:36px}
.foot-grid h2{color:#fff;font-size:.95rem;margin-bottom:14px}
.foot-grid ul{list-style:none;margin:0;padding:0}
.foot-grid li{margin-bottom:9px}
.foot-grid a{color:#CBD5E1;font-size:.94rem}
.foot-grid a:hover{color:#fff}
.foot-brand p{font-size:.94rem;color:#94A3B8;max-width:32em;margin-top:12px}
.foot-bottom{display:flex;flex-wrap:wrap;gap:8px 20px;justify-content:space-between;align-items:center;border-top:1px solid rgba(255,255,255,.1);padding-top:20px;font-size:.88rem;color:#94A3B8}
.foot-bottom p{margin:0}
.foot-bottom a{color:#CBD5E1}
.attr-sec .widget-content{display:inline}

/* ---------- Cookie banner / toast ---------- */
.cookie{position:fixed;left:16px;right:16px;bottom:calc(16px + env(safe-area-inset-bottom,0));z-index:200;max-width:760px;margin:0 auto;display:flex;gap:16px;align-items:center;flex-wrap:wrap;background:var(--navy);color:#E2E8F0;border:1px solid rgba(255,255,255,.14);border-radius:14px;padding:16px 18px;box-shadow:0 18px 50px rgba(0,0,0,.4)}
.cookie p{margin:0;flex:1 1 280px;font-size:.92rem}
.cookie a{color:#93C5FD;text-decoration:underline}
.cookie .btn{background:rgba(255,255,255,.08);color:#fff;border-color:rgba(255,255,255,.25)}
.cookie .btn-primary{background:var(--brand);border-color:var(--brand)}
.toast{position:fixed;left:50%;bottom:28px;transform:translate(-50%,30px);background:#0F172A;color:#fff;padding:11px 20px;border-radius:99px;font-size:.92rem;font-weight:600;opacity:0;pointer-events:none;transition:all .25s;z-index:300;border:1px solid rgba(255,255,255,.15)}
.toast.show{opacity:1;transform:translate(-50%,0)}

/* ---------- Mode switching (set by JS) ---------- */
#view-home,#view-route{display:none}
.m-home #view-home,.m-route #view-route{display:block}
.m-route #blog-wrap{display:none}
.pt-index:not(.m-blog):not(.m-home) #blog-wrap{visibility:hidden}

/* ---------- Responsive ---------- */
@media (max-width:1000px){
  .hero-in{grid-template-columns:1fr;gap:32px}
  .tool-layout{grid-template-columns:1fr}
  .side{position:static}
  .foot-grid{grid-template-columns:1fr 1fr}
}
@media (max-width:820px){
  .menu-btn{display:grid}
  .nav{position:absolute;left:0;right:0;top:100%;flex-direction:column;background:var(--navy);padding:10px 16px 16px;border-bottom:1px solid rgba(255,255,255,.1);display:none;margin:0}
  .nav.open{display:flex}
  .nav a{padding:12px}
  .hdr-search input,.hdr-search input:focus{width:150px}
}
@media (max-width:600px){
  .grid2,.grid3,.cmp{grid-template-columns:1fr}
  .hero{padding:48px 0 44px}
  .sec{padding:44px 0}
  .article{padding:20px}
  .tool-box{padding:18px}
  .foot-grid{grid-template-columns:1fr}
  .hdr-search{display:none}
  .hdr{gap:10px}
}
@media (prefers-reduced-motion:reduce){*{transition:none !important;scroll-behavior:auto !important}}

body.script:
//
/* =====================================================================
   CORE  (config, helpers, router, home page, header/footer, SEO)
   Each tool lives in its own <script> block below, so one tool can
   never break another one.
   ===================================================================== */
window.TH=(function(){
"use strict";

/* ============================ SITE CONFIG ============================
   Edit the values below. Everything else works automatically.        */
var CONFIG={
  siteName:'',                                   // '' = use your Blogger blog title (Settings > Title)
  tagline:'Free online tools that run privately in your browser',
  email:'gamesforkids001@gmail.com',             // Your real contact email
  lastUpdated:'September 22, 2026',              // shown in footer and on every tool page
  brandColor:'#2563EB',                          // main blue (buttons, links)
  accentColor:'#14B8A6',                         // teal accent
  usePageUrls:true                               // false: links like /#/word-counter (NOT reliably indexed as separate pages by Google)
                                                 // true : links like /p/word-counter.html - REQUIRES creating a Blogger Page for
                                                 // every slug below with a matching custom permalink. See the setup table sent
                                                 // with this theme. Until every Page exists, links for missing slugs will 404.
};
/* ===================================================================== */

var doc=document, root=doc.documentElement, body=doc.body;
function $(s,r){return (r||doc).querySelector(s);}
function $$(s,r){return Array.prototype.slice.call((r||doc).querySelectorAll(s));}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function strip(h){var t=doc.createElement('textarea');t.innerHTML=String(h).replace(/<[^>]+>/g,'');return t.value.replace(/\s+/g,' ').trim();}
function store(k,v){try{if(v===undefined){return localStorage.getItem(k);}localStorage.setItem(k,v);}catch(e){}return null;}
function debounce(fn,ms){var t;return function(){var a=arguments,c=this;clearTimeout(t);t=setTimeout(function(){fn.apply(c,a);},ms||150);};}

/* ---------- Inline SVG icons (24x24 stroke icons) ---------- */
var ICONS={
 file:'<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h6"/>',
 type:'<path d="M4 7V5h16v2M12 5v14M9 19h6"/>',
 lock:'<rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',
 qr:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 14h3v3h-3zM20 14v.01M14 20h3M20 17v4"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/>',
 activity:'<path d="M22 12h-4l-3 9L9 3l-3 9H2"/>',
 repeat:'<path d="M17 3l4 4-4 4M3 7h18M7 21l-4-4 4-4M21 17H3"/>',
 braces:'<path d="M8 3H7a2 2 0 0 0-2 2v4a2 2 0 0 1-2 2 2 2 0 0 1 2 2v4a2 2 0 0 0 2 2h1M16 3h1a2 2 0 0 1 2 2v4a2 2 0 0 0 2 2 2 2 0 0 0-2 2v4a2 2 0 0 1-2 2h-1"/>',
 image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-5-5L5 21"/>',
 drop:'<path d="M12 2.7l5.7 5.7a8 8 0 1 1-11.4 0z"/>',
 search:'<circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/>',
 copy:'<rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>',
 check:'<path d="M20 6 9 17l-5-5"/>',
 shield:'<path d="M12 3 4 6v6c0 5 3.4 8 8 9 4.6-1 8-4 8-9V6z"/><path d="m9 12 2 2 4-4"/>',
 zap:'<path d="M13 2 4 14h7l-1 8 9-12h-7z"/>',
 phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M11 18h2"/>',
 gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M12 8v13M19 12v9H5v-9M7.5 8a2.5 2.5 0 0 1 0-5C11 3 12 8 12 8s1-5 4.5-5a2.5 2.5 0 0 1 0 5"/>',
 mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
 download:'<path d="M12 3v12m0 0-4-4m4 4 4-4M4 21h16"/>',
 upload:'<path d="M12 15V3m0 0L8 7m4-4 4 4M4 21h16"/>',
 trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14"/>',
 refresh:'<path d="M21 12a9 9 0 0 1-15.5 6.2L3 16m0 5v-5h5M3 12a9 9 0 0 1 15.5-6.2L21 8m0-5v5h-5"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
 moon:'<path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/>',
 users:'<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20c0-3.6 2.9-6 6.5-6s6.5 2.4 6.5 6M17 4.5a3.5 3.5 0 0 1 0 7M21.5 20c0-2.6-1.6-4.6-4-5.5"/>',
 globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/>',
 pipette:'<path d="M14 4l6 6M4 20l1-4 9-9 4 4-9 9z"/>',
 swap:'<path d="M7 4 3 8l4 4M3 8h14M17 20l4-4-4-4M21 16H7"/>',
 paste:'<rect x="8" y="3" width="8" height="4" rx="1"/><path d="M8 5H6a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-2"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 close:'<path d="M18 6 6 18M6 6l12 12"/>',
 layers:'<path d="m12 2 9 5-9 5-9-5 9-5z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',
 scissors:'<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="M20 4 8.1 15.9M14.5 14.5 20 20M8.1 8.1 12 12"/>',
 rotate:'<path d="M21 12a9 9 0 1 1-3-6.7"/><path d="M21 3v6h-6"/>',
 maximize:'<path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3M3 16v3a2 2 0 0 0 2 2h3m11-5v3a2 2 0 0 1-2 2h-3"/>',
 crop:'<path d="M6 2v14a2 2 0 0 0 2 2h14"/><path d="M18 22V8a2 2 0 0 0-2-2H2"/>',
 list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',
 dice:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><circle cx="16" cy="8" r="1"/><circle cx="8" cy="16" r="1"/><circle cx="16" cy="16" r="1"/><circle cx="12" cy="12" r="1"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 16v-5M12 8h.01"/>'
};
function icon(n,c){return '<svg class="ico'+(c?' '+c:'')+'" viewBox="0 0 24 24" aria-hidden="true">'+(ICONS[n]||'')+'</svg>';}

/* ---------- Small UI helpers ---------- */
var tt;
function toast(m){var t=$('#toast');if(!t){return;}t.textContent=m;t.classList.add('show');clearTimeout(tt);tt=setTimeout(function(){t.classList.remove('show');},1900);}
function copy(text,label){
  function done(){toast(label||'Copied to clipboard');}
  function fallback(){var t=doc.createElement('textarea');t.value=text;t.setAttribute('readonly','');t.style.cssText='position:fixed;left:-9999px;top:0';doc.body.appendChild(t);t.select();var ok=false;try{ok=doc.execCommand('copy');}catch(e){}doc.body.removeChild(t);if(ok){done();}else{toast('Copy failed. Please copy manually.');}}
  if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(done,fallback);}else{fallback();}
}
function saveBlob(blob,name){var a=doc.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;doc.body.appendChild(a);a.click();setTimeout(function(){doc.body.removeChild(a);URL.revokeObjectURL(u);},800);}
function fmtNum(n,d){if(!isFinite(n)){return '-';}return Number(n).toLocaleString('en-US',{maximumFractionDigits:d===undefined?2:d});}
function bytes(n){if(n<1024){return n+' B';}if(n<1048576){return (n/1024).toFixed(1)+' KB';}return (n/1048576).toFixed(2)+' MB';}

/* ---------- Page data from the Blogger template ---------- */
var PG=$('#pgdata');
var BASE=(PG&&PG.getAttribute('data-home'))||(location.protocol+'//'+location.host+'/');
if(BASE.slice(-1)!=='/'){BASE+='/';}
var PT=(PG&&PG.getAttribute('data-type'))||'index';
var BLOG_TITLE=(PG&&PG.getAttribute('data-title'))||'Online Tools';
var BLOG_DESC=(PG&&PG.getAttribute('data-desc'))||CONFIG.tagline;
var SITE=CONFIG.siteName||BLOG_TITLE;
var isHome=PT==='index'&&/^\/(index\.html)?$/.test(location.pathname)&&!/[?&](updated-max|q)=/.test(location.search);

var TH={CONFIG:CONFIG,tools:[],pages:{},$:$,$$:$$,esc:esc,strip:strip,icon:icon,copy:copy,toast:toast,saveBlob:saveBlob,fmt:fmtNum,bytes:bytes,debounce:debounce,store:store};
var cleanups=[];
TH.onLeave=function(fn){cleanups.push(fn);};
function runCleanups(){while(cleanups.length){try{cleanups.pop()();}catch(e){}}}
TH.add=function(d){d.type='tool';TH.tools.push(d);};
TH.addPage=function(d){d.type='page';TH.pages[d.slug]=d;};
function find(s){var i;for(i=0;i<TH.tools.length;i++){if(TH.tools[i].slug===s){return TH.tools[i];}}return TH.pages[s]||null;}

/* ---------- Links ---------- */
function routeHref(s){
  if(s==='home'){return BASE;}
  if(CONFIG.usePageUrls&&find(s)){return BASE+'p/'+s+'.html';}
  return BASE+'#/'+s;
}
function fixLinks(scope){$$('a[data-route]',scope||doc).forEach(function(a){a.setAttribute('href',routeHref(a.getAttribute('data-route')));});}

/* ---------- SEO (title, meta, Open Graph, JSON-LD) ---------- */
var ORIG=null;
function setMeta(name,val,prop){
  var sel='meta['+(prop?'property':'name')+'="'+name+'"]',el=$(sel);
  if(!el){el=doc.createElement('meta');el.setAttribute(prop?'property':'name',name);doc.head.appendChild(el);}
  el.setAttribute('content',val);
}
function getMeta(name){var el=$('meta[name="'+name+'"]');return el?el.getAttribute('content'):'';}
function setSeo(o){
  if(!ORIG){ORIG={title:doc.title,desc:getMeta('description')||BLOG_DESC};}
  doc.title=o.title;
  setMeta('description',o.desc);
  setMeta('og:title',o.title,true);setMeta('og:description',o.desc,true);
  if(o.url){
    setMeta('og:url',o.url,true);
    /* Keep <link rel="canonical"> in sync with the real, fragment-free page URL.
       Only done when usePageUrls is on, because a canonical must point at a
       real indexable URL - a #/hash address is not one, so in hash mode we
       leave Blogger's own server-rendered canonical (the homepage URL) alone. */
    if(CONFIG.usePageUrls){
      var can=$('link[rel="canonical"]');
      if(!can){can=doc.createElement('link');can.setAttribute('rel','canonical');doc.head.appendChild(can);}
      can.setAttribute('href',o.url);
    }
  }
  setMeta('twitter:card','summary');setMeta('twitter:title',o.title);setMeta('twitter:description',o.desc);
  var old=$('#ld-route');if(old){old.parentNode.removeChild(old);}
  if(o.ld){var s=doc.createElement('script');s.type='application/ld+json';s.id='ld-route';s.text=JSON.stringify(o.ld);doc.head.appendChild(s);}
}
var HOME_FAQ=[
 ['Are these online tools really free?','Yes. Every tool on this website is free to use, with no trial period, no usage limits and no hidden charges. The site is supported by optional advertising.'],
 ['Do you upload or store my text, files or images?','No. The tools run entirely in your browser using JavaScript. The text you type, the images you compress and the passwords you generate stay on your device and are never sent to our servers.'],
 ['Do I need to create an account?','No account, email address or sign-up is needed. Open a tool and start using it straight away.'],
 ['Do the tools work on mobile phones and tablets?','Yes. The whole website is responsive and every tool has been designed for touch screens as well as desktop computers. Current versions of Chrome, Safari, Edge and Firefox are supported.'],
 ['How accurate are the calculators and converters?','Conversion factors follow international standards and calculations use double-precision arithmetic. The BMI and age results are informational; for medical or legal decisions please consult a qualified professional.'],
 ['Can I suggest a new tool or report a problem?','Please do. Use the Contact page to send us your idea or describe the issue, including the browser you use, and we will look into it.']
];
function homeLd(){
  return {'@context':'https://schema.org','@graph':[
    {'@type':'WebSite','name':SITE,'url':BASE,'description':CONFIG.tagline,'potentialAction':{'@type':'SearchAction','target':BASE+'search?q={search_term_string}','query-input':'required name=search_term_string'}},
    {'@type':'FAQPage','mainEntity':HOME_FAQ.map(function(f){return {'@type':'Question','name':f[0],'acceptedAnswer':{'@type':'Answer','text':f[1]}};})}
  ]};
}
function seoHome(){
  setSeo({title:(ORIG&&ORIG.title)||doc.title,desc:(ORIG&&ORIG.desc)||BLOG_DESC,url:BASE,ld:homeLd()});
}

/* ---------- Header: navigation, search, theme, menu ---------- */
var NAV=[['Home','home'],['Tools','tools'],['Articles','articles'],['About','about-us'],['Contact','contact-us']];
function buildNav(){
  var n=$('#main-nav');if(!n){return;}
  n.innerHTML=NAV.map(function(x){return '<a data-r="'+x[1]+'" data-route="'+x[1]+'" href="#">'+x[0]+'</a>';}).join('');
  $$('a',n).forEach(function(a){var r=a.getAttribute('data-r');a.setAttribute('href',(r==='tools'||r==='articles')?BASE+'#/'+r:routeHref(r));a.removeAttribute('data-route');});
  $$('a',n).forEach(function(a){a.addEventListener('click',function(){n.classList.remove('open');var b=$('#menu-btn');if(b){b.setAttribute('aria-expanded','false');}});});
}
function buildTheme(){
  var b=$('#theme-btn');if(!b){return;}
  function sync(){var d=root.getAttribute('data-theme')==='dark';b.innerHTML=icon(d?'sun':'moon');b.setAttribute('aria-label',d?'Switch to light mode':'Switch to dark mode');}
  b.addEventListener('click',function(){var d=root.getAttribute('data-theme')==='dark'?'light':'dark';root.setAttribute('data-theme',d);store('th',d);sync();});
  sync();
}
function buildMenu(){
  var b=$('#menu-btn'),n=$('#main-nav');if(!b||!n){return;}
  b.addEventListener('click',function(){var o=n.classList.toggle('open');b.setAttribute('aria-expanded',o?'true':'false');b.setAttribute('aria-label',o?'Close menu':'Open menu');});
}
function toolMatch(t,q){
  var hay=(t.name+' '+t.short+' '+t.kw+' '+t.cat).toLowerCase(),parts=q.toLowerCase().split(/\s+/).filter(Boolean);
  return parts.every(function(p){return hay.indexOf(p)!==-1;});
}
function buildSearch(){
  var inp=$('#hs'),res=$('#hs-res');if(!inp||!res){return;}
  var sel=-1,items=[];
  function close(){res.hidden=true;sel=-1;}
  function paint(){$$('a',res).forEach(function(a,i){a.classList.toggle('sel',i===sel);});}
  function show(){
    var q=inp.value.trim();if(!q){close();return;}
    items=TH.tools.filter(function(t){return toolMatch(t,q);}).slice(0,6);
    if(items.length){res.innerHTML=items.map(function(t){return '<li><a href="'+routeHref(t.slug)+'">'+icon(t.icon)+'<span>'+esc(t.name)+'<small>'+esc(t.short)+'</small></span></a></li>';}).join('');}
    else{res.innerHTML='<li class="hs-empty">No tool found. <a href="'+BASE+'search?q='+encodeURIComponent(q)+'">Search articles instead</a></li>';}
    res.hidden=false;sel=-1;
  }
  inp.addEventListener('input',show);
  inp.addEventListener('focus',show);
  inp.addEventListener('keydown',function(e){
    var links=$$('a',res);
    if(e.key==='ArrowDown'){e.preventDefault();sel=Math.min(sel+1,links.length-1);paint();}
    else if(e.key==='ArrowUp'){e.preventDefault();sel=Math.max(sel-1,0);paint();}
    else if(e.key==='Escape'){close();inp.blur();}
    else if(e.key==='Enter'){
      e.preventDefault();
      var t=links[sel>=0?sel:0];
      if(t){t.click();if(t.href){location.href=t.href;}close();inp.value='';}
      else if(inp.value.trim()){location.href=BASE+'search?q='+encodeURIComponent(inp.value.trim());}
    }
  });
  doc.addEventListener('click',function(e){if(!e.target.closest||!e.target.closest('.hdr-search')){close();}});
  res.addEventListener('click',function(){setTimeout(function(){close();inp.value='';},0);});
}

/* ---------- Footer ---------- */
function buildFooter(){
