  var half=Math.ceil(TH.tools.length/2);
  function list(a){return '<ul>'+a.map(function(t){return '<li><a href="'+routeHref(t.slug)+'">'+esc(t.name)+'</a></li>';}).join('')+'</ul>';}
  var pages=[['About Us','about-us'],['Contact Us','contact-us'],['Privacy Policy','privacy-policy'],['Terms &amp; Conditions','terms-and-conditions'],['Disclaimer','disclaimer']];
  f.innerHTML='<div class="foot-brand"><a class="brand" href="'+BASE+'"><span class="brand-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14.7 6.3a4 4 0 0 0-5.4 5.4L3 18l3 3 6.3-6.3a4 4 0 0 0 5.4-5.4l-2.6 2.6-2.4-.6-.6-2.4z"/></svg></span><span>'+esc(SITE)+'</span></a><p>'+esc(CONFIG.tagline)+'. No sign-up, no uploads and no tracking of what you type.</p></div>'
   +'<div><h2>Popular tools</h2>'+list(TH.tools.slice(0,half))+'</div>'
   +'<div><h2>More tools</h2>'+list(TH.tools.slice(half))+'</div>'
   +'<div><h2>Company</h2><ul>'+pages.map(function(p){return '<li><a href="'+routeHref(p[1])+'">'+p[0]+'</a></li>';}).join('')+'<li><a href="#" id="ck-open">Cookie settings</a></li></ul></div>';
  var c=$('#foot-copy'),u=$('#foot-updated');
  if(c){c.textContent='\u00A9 '+new Date().getFullYear()+' '+SITE+'. All rights reserved.';}
  if(u){u.textContent='Last updated: '+CONFIG.lastUpdated;}
  var o=$('#ck-open');if(o){o.addEventListener('click',function(e){e.preventDefault();var b=$('#cookie-banner');if(b){b.hidden=false;}});}
}

/* ---------- Cookie / consent banner ---------- */
function buildCookie(){
  var b=$('#cookie-banner');if(!b){return;}
  function fire(v){try{window.dispatchEvent(new CustomEvent('th-consent',{detail:v}));}catch(e){}}
  if(!store('consent')){b.hidden=false;}else{fire(store('consent'));}
  $('#ck-accept').addEventListener('click',function(){store('consent','accepted');b.hidden=true;fire('accepted');toast('Preferences saved');});
  $('#ck-reject').addEventListener('click',function(){store('consent','rejected');b.hidden=true;fire('rejected');toast('Preferences saved');});
}

/* ---------- Home page ---------- */
var CATS=['All','PDF & Files','Text','Security','Calculators','Developer','Design & Media'];
var state={cat:'All',q:''};
function toolCard(t){
  return '<a class="tool-card" href="'+routeHref(t.slug)+'"><span class="tc-ico">'+icon(t.icon)+'</span><h3>'+esc(t.name)+'</h3><p>'+esc(t.short)+'</p><span class="tc-cat">'+esc(t.cat)+'</span></a>';
}
function paintGrid(){
  var g=$('#tool-grid');if(!g){return;}
  var list=TH.tools.filter(function(t){return (state.cat==='All'||t.cat===state.cat)&&(!state.q||toolMatch(t,state.q));});
  g.innerHTML=list.length?list.map(toolCard).join(''):'<div class="empty" style="grid-column:1/-1">No tools match your search. Try a different word or choose another category.</div>';
  $$('.chip').forEach(function(c){c.setAttribute('aria-pressed',c.getAttribute('data-cat')===state.cat?'true':'false');});
}
function buildHome(){
  var h=$('#view-home');if(!h||h.getAttribute('data-built')){return;}
  var pop=TH.tools.slice(0,4).map(function(t){return '<a href="'+routeHref(t.slug)+'">'+esc(t.name)+'</a>';}).join('');
  var why=[
   ['shield','Private by design','Text, files and images are processed inside your browser. Nothing is uploaded, stored or shared.'],
   ['zap','Instant results','No waiting, no queues. Results update as you type because the work happens on your own device.'],
   ['gift','Free, without sign-up','Use every tool as often as you like. There is no account to create and no premium tier.'],
   ['phone','Works on every screen','A responsive layout with large touch targets makes each tool comfortable on phones and tablets.'],
   ['check','Accurate and dependable','Standard formulas and conversion factors, tested on the latest versions of major browsers.'],
   ['globe','Ready when you are','Nothing to install and no plugins required. Open the page, use the tool, close the tab.']
  ];
  h.innerHTML=
   '<section class="hero"><div class="container hero-in"><div>'
   +'<h1>Free online tools that work instantly in your browser</h1>'
   +'<p class="lead">Count words, generate strong passwords and QR codes, compress images, format JSON and more. No sign-up, no uploads: everything runs privately on your device.</p>'
   +'<div class="hero-search" role="search">'+icon('search')+'<input id="hero-q" type="search" autocomplete="off" placeholder="Search '+TH.tools.length+' free tools, for example password or QR" aria-label="Search tools"></div>'
   +'<div class="quick"><span>Popular:</span>'+pop+'</div></div>'
   +'<div class="hero-card"><h2>Why people choose '+esc(SITE)+'</h2>'
   +'<div class="hc-row">'+icon('shield')+'<div><b>Your data stays with you</b><span>Everything is processed locally</span></div></div>'
   +'<div class="hc-row">'+icon('zap')+'<div><b>Instant, live results</b><span>No page reloads or waiting</span></div></div>'
   +'<div class="hc-row">'+icon('gift')+'<div><b>Free forever</b><span>No account, no limits</span></div></div>'
   +'<div class="hc-row">'+icon('phone')+'<div><b>Made for every device</b><span>Phone, tablet and desktop</span></div></div></div>'
   +'</div></section>'
   +'<section class="sec" id="tools"><div class="container"><div class="sec-head"><h2>All tools</h2><p>Choose a tool below. Each one opens on its own page with a short guide and answers to common questions.</p></div>'
   +'<div class="chips" role="group" aria-label="Filter tools by category">'+CATS.map(function(c){return '<button class="chip" type="button" data-cat="'+esc(c)+'" aria-pressed="'+(c==='All'?'true':'false')+'">'+esc(c)+'</button>';}).join('')+'</div>'
   +'<div class="tool-grid" id="tool-grid"></div></div></section>'
   +'<section class="sec alt" id="why"><div class="container"><div class="sec-head"><h2>Why choose us</h2><p>Simple tools, built carefully, with your privacy as the starting point.</p></div><div class="why-grid">'
   +why.map(function(w){return '<div class="why"><span class="tc-ico">'+icon(w[0])+'</span><div><h3>'+w[1]+'</h3><p>'+w[2]+'</p></div></div>';}).join('')
   +'</div></div></section>'
   +'<section class="sec" id="articles"><div class="container"><div class="sec-head"><h2>Latest articles</h2><p>Guides, tips and explanations to help you get more from our tools.</p></div><div id="articles-slot"></div><p class="more-link"><a class="btn" href="'+BASE+'search?max-results=12">Browse all articles</a></p></div></section>'
   +'<section class="sec alt faq" id="faq"><div class="container"><div class="sec-head"><h2>Frequently asked questions</h2></div>'
   +HOME_FAQ.map(function(f){return '<details><summary>'+esc(f[0])+'</summary><p>'+esc(f[1])+'</p></details>';}).join('')
   +'<p class="updated">Last updated: '+esc(CONFIG.lastUpdated)+'. Your data never leaves your browser.</p></div></section>';
  h.setAttribute('data-built','1');
  $$('.chip',h).forEach(function(c){c.addEventListener('click',function(){state.cat=c.getAttribute('data-cat');paintGrid();});});
  var q=$('#hero-q');
  if(q){
    q.addEventListener('input',function(){state.q=q.value.trim();paintGrid();});
    q.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();var t=$('#tools');if(t){t.scrollIntoView();}}});
  }
  paintGrid();
}
function mountBlog(){
  var w=$('#blog-wrap'),slot=$('#articles-slot');
  if(w&&slot&&w.parentNode!==slot){slot.appendChild(w);}
  var t=w&&$('.archive-title',w);if(t){t.parentNode.removeChild(t);}
  var n=w?$$('.post-card',w).length:0;
  var sec=$('#articles');if(sec){sec.hidden=!n;}
}

/* ---------- Tool / info pages ---------- */
function articleHtml(d){
  var a=d.art||{},h='';
  h+='<h2>About the '+esc(d.name)+'</h2>'+(a.intro||[]).map(function(p){return '<p>'+p+'</p>';}).join('');
  h+='<h2>How to use the '+esc(d.name)+'</h2><ol>'+(a.steps||[]).map(function(s){return '<li>'+s+'</li>';}).join('')+'</ol>';
  h+='<h2>Key features</h2><ul>'+(a.features||[]).map(function(s){return '<li>'+s+'</li>';}).join('')+'</ul>';
  h+='<h2>Common use cases</h2><ul>'+(a.uses||[]).map(function(s){return '<li>'+s+'</li>';}).join('')+'</ul>';
  h+='<h2>Frequently asked questions</h2>'+(a.faqs||[]).map(function(f){return '<h3>'+esc(f[0])+'</h3><p>'+f[1]+'</p>';}).join('');
  h+='<p class="updated">Last updated: '+esc(CONFIG.lastUpdated)+'. This tool runs in your browser and your data never leaves your device.</p>';
  return h;
}
function toolLd(d){
  var url=routeHref(d.slug),a=d.art||{};
  return {'@context':'https://schema.org','@graph':[
    {'@type':'WebApplication','name':d.h1||d.name,'url':url,'description':d.desc,'applicationCategory':'UtilitiesApplication','operatingSystem':'Any (web browser)','browserRequirements':'Requires JavaScript','isAccessibleForFree':true,'offers':{'@type':'Offer','price':'0','priceCurrency':'USD'}},
    {'@type':'FAQPage','mainEntity':(a.faqs||[]).map(function(f){return {'@type':'Question','name':f[0],'acceptedAnswer':{'@type':'Answer','text':strip(f[1])}};})},
    {'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':BASE},{'@type':'ListItem','position':2,'name':d.name,'item':url}]}
  ]};
}
function related(d){
  var same=TH.tools.filter(function(t){return t.slug!==d.slug&&t.cat===d.cat;});
  var rest=TH.tools.filter(function(t){return t.slug!==d.slug&&t.cat!==d.cat;});
  return same.concat(rest).slice(0,5);
}
function renderRoute(slug){
  var d=find(slug),crumb=$('#rt-crumb'),head=$('#rt-head'),ui=$('#rt-ui'),art=$('#rt-article'),rel=$('#rt-related'),view=$('#view-route');
  view.classList.toggle('legal',!d||d.type==='page');
  if(!d){
    crumb.innerHTML='<ol><li><a href="'+BASE+'">Home</a></li><li>Page not found</li></ol>';
    head.innerHTML='';ui.hidden=true;
    art.innerHTML='<h1>Page not found</h1><p>We could not find that page. It may have been moved or the address may be mistyped. Pick a tool from the list below or return to the homepage.</p><p><a class="btn btn-primary" href="'+BASE+'">Go to homepage</a></p>';
    rel.innerHTML='<h2>Popular tools</h2>'+TH.tools.slice(0,5).map(relItem).join('');
    setSeo({title:'Page not found | '+SITE,desc:'The page you requested could not be found.',url:BASE});
    return;
  }
  rel.innerHTML='<h2>'+(d.type==='tool'?'Related tools':'Popular tools')+'</h2>'+(d.type==='tool'?related(d):TH.tools.slice(0,5)).map(relItem).join('');
  if(d.type==='tool'){
    crumb.innerHTML='<ol><li><a href="'+BASE+'">Home</a></li><li><a href="'+BASE+'#/tools">Tools</a></li><li aria-current="page">'+esc(d.name)+'</li></ol>';
    head.innerHTML='<div class="tool-head"><span class="tc-ico">'+icon(d.icon)+'</span><div><h1>'+esc(d.h1||d.name)+'</h1><p>'+esc(d.short)+'</p><span class="trust">'+icon('shield')+'Runs in your browser. Your data never leaves your device.</span></div></div>';
    ui.hidden=false;ui.innerHTML='';
    try{d.render(ui);}catch(e){ui.innerHTML='<div class="msg err">Sorry, this tool could not start. Please refresh the page or try another browser.</div>';if(window.console){console.error(e);}}
    art.innerHTML=articleHtml(d);
    setSeo({title:d.title+' | '+SITE,desc:d.desc,url:routeHref(d.slug),ld:toolLd(d)});
  }else{
    crumb.innerHTML='<ol><li><a href="'+BASE+'">Home</a></li><li aria-current="page">'+esc(d.title)+'</li></ol>';
    head.innerHTML='';ui.hidden=true;ui.innerHTML='';
    art.innerHTML='<h1>'+esc(d.title)+'</h1>'+d.html.replace(/\{EMAIL\}/g,esc(CONFIG.email)).replace(/\{SITE\}/g,esc(SITE)).replace(/\{UPDATED\}/g,esc(CONFIG.lastUpdated)).replace(/\{HOME\}/g,esc(BASE));
    setSeo({title:d.title+' | '+SITE,desc:d.desc,url:routeHref(d.slug)});
    if(d.after){try{d.after(art);}catch(e){}}
  }
  fixLinks(view);
}
function relItem(t){return '<a class="rel" href="'+routeHref(t.slug)+'"><span class="tc-ico">'+icon(t.icon)+'</span><span><b>'+esc(t.name)+'</b><small>'+esc(t.short)+'</small></span></a>';}

/* ---------- Router ---------- */
function bodyTextLen(){var b=$('.post-body');return b?b.textContent.replace(/\s+/g,' ').trim().length:0;}
function routeFromLocation(){
  var h=location.hash.replace(/^#\/?/,'');
  try{h=decodeURIComponent(h);}catch(e){}
  h=h.toLowerCase().replace(/\/+$/,'').replace(/[?].*$/,'');
  if(isHome){return h||'home';}
  if(PT==='static_page'){
    var m=location.pathname.match(/\/p\/([^\/]+?)\.html$/);
    if(m){var d=find(m[1]);if(d&&(d.type==='tool'||bodyTextLen()<300)){return m[1];}}
  }
  return null;
}
function setMode(m){body.classList.remove('m-home','m-route','m-blog');body.classList.add('m-'+m);}
var firstRun=true;
function route(){
  var r=routeFromLocation();
  runCleanups();
  if(r===null){setMode('blog');afterBlog();markNav('');return;}
  if(r==='home'||r==='tools'||r==='articles'||r==='faq'||r==='why'){
    buildHome();setMode('home');mountBlog();seoHome();
    var el=(r==='home')?null:$('#'+r);
    if(el){el.scrollIntoView();}else if(!firstRun){window.scrollTo(0,0);}
    markNav(r);firstRun=false;return;
  }
  var d=find(r);
  setMode('route');renderRoute(r);
  markNav(d&&d.type==='tool'?'tools':r);
  if(!firstRun){window.scrollTo(0,0);var c=$('#content');if(c){c.focus({preventScroll:true});}}
  firstRun=false;
}
function markNav(r){$$('#main-nav a').forEach(function(a){a.classList.toggle('on',a.getAttribute('data-r')===r);});}

/* ---------- Extras on normal Blogger pages (posts, labels, search) ---------- */
function afterBlog(){
  if(PT!=='item'){return;}
  var p=$('.post.full');if(!p||$('.share',p)){return;}
  var u=encodeURIComponent(location.href.split('#')[0]),t=encodeURIComponent(doc.title);
  var s=doc.createElement('div');s.className='share';
  s.innerHTML='<strong>Share:</strong>'
   +'<a class="btn btn-sm" target="_blank" rel="noopener" href="https://wa.me/?text='+t+'%20'+u+'">WhatsApp</a>'
   +'<a class="btn btn-sm" target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u='+u+'">Facebook</a>'
   +'<a class="btn btn-sm" target="_blank" rel="noopener" href="https://twitter.com/intent/tweet?url='+u+'&text='+t+'">X</a>'
   +'<button class="btn btn-sm" type="button" id="copy-link">Copy link</button>';
  p.appendChild(s);
  $('#copy-link').addEventListener('click',function(){copy(location.href.split('#')[0],'Link copied');});
}

/* ---------- Start ---------- */
TH.boot=function(){
  try{root.style.setProperty('--brand',CONFIG.brandColor);root.style.setProperty('--accent',CONFIG.accentColor);
    var bn=$('#brand-name');if(bn&&CONFIG.siteName){bn.textContent=CONFIG.siteName;}}catch(e){}
  try{buildTheme();}catch(e){}
  try{buildMenu();}catch(e){}
  try{buildNav();}catch(e){}
  try{buildSearch();}catch(e){}
  try{buildFooter();}catch(e){}
  try{buildCookie();}catch(e){}
  try{fixLinks(doc);}catch(e){}
  try{route();}catch(e){if(window.console){console.error(e);}setMode('blog');}
  window.addEventListener('hashchange',function(){try{route();}catch(e){if(window.console){console.error(e);}}});
};
return TH;
})();

