/* =====================================================================
   TOOL 1: WORD & CHARACTER COUNTER
   ===================================================================== */
(function(TH){try{
var $=TH.$,icon=TH.icon;
TH.add({
 slug:'word-counter',name:'Word Counter',h1:'Word & Character Counter',cat:'Text',icon:'file',
 short:'Count words, characters, sentences and paragraphs, with reading time and keyword density.',
 kw:'word count character count text length paragraph sentence reading time keyword density essay seo',
 title:'Word Counter: Count Words, Characters & Reading Time',
 desc:'Free online word counter. Count words, characters, sentences and paragraphs instantly, and see reading time and keyword density. Private and runs in your browser.',
 render:function(root){
  root.innerHTML=
   '<div class="field"><label for="wc-in">Type or paste your text</label><textarea id="wc-in" placeholder="Start typing or paste your text here..." spellcheck="true"></textarea></div>'
   +'<div class="btn-row" style="margin-top:0">'
   +'<button class="btn" type="button" id="wc-paste">'+icon('paste')+'Paste</button>'
   +'<button class="btn" type="button" id="wc-sample">Sample text</button>'
   +'<button class="btn" type="button" id="wc-copy">'+icon('copy')+'Copy text</button>'
   +'<button class="btn" type="button" id="wc-clear">'+icon('trash')+'Clear</button></div>'
   +'<div class="stats" id="wc-stats"></div>'
   +'<h2 style="font-size:1.15rem;margin-top:8px">Keyword density</h2>'
   +'<label class="chk" style="margin-bottom:10px"><input type="checkbox" id="wc-stop" checked> Ignore common words such as &ldquo;the&rdquo; and &ldquo;and&rdquo;</label>'
   +'<div id="wc-kw"></div>';
  var inp=$('#wc-in',root),st=$('#wc-stats',root),kw=$('#wc-kw',root),stop=$('#wc-stop',root);
  var STOP='a an the and or but if of to in on at by for with from as is are was were be been being it its this that these those you he she we they me my your our their not no so do does did have has had will would can could should than then there here what which who whom how when where why into about over under also just very'.split(' ');
  function dur(sec){if(sec<1){return '0 sec';}if(sec<60){return Math.round(sec)+' sec';}var m=Math.floor(sec/60),s=Math.round(sec%60);return m+' min'+(s?' '+s+' sec':'');}
  function calc(){
    var t=inp.value,tr=t.trim();
    var words=tr?(tr.match(/\S+/g)||[]):[];
    var sent=tr?tr.split(/[.!?\u06D4\u061F]+(?:\s|$)/).filter(function(s){return s.trim();}).length:0;
    var paras=tr?tr.split(/\n\s*\n/).filter(function(s){return s.trim();}).length:0;
    var n=words.length;
    var cells=[[n,'Words'],[t.length,'Characters'],[t.replace(/\s/g,'').length,'Characters (no spaces)'],[sent,'Sentences'],[paras,'Paragraphs'],[dur(n/200*60),'Reading time'],[dur(n/130*60),'Speaking time']];
    st.innerHTML=cells.map(function(c){return '<div class="stat"><b>'+(typeof c[0]==='number'?TH.fmt(c[0],0):c[0])+'</b><span>'+c[1]+'</span></div>';}).join('');
    var list=tr.toLowerCase().match(/[\p{L}\p{N}'\u2019-]+/gu)||[],map={},total=list.length;
    list.forEach(function(w){w=w.replace(/^['\u2019-]+|['\u2019-]+$/g,'');if(!w){return;}if(stop.checked&&(w.length<3||STOP.indexOf(w)!==-1)){return;}map[w]=(map[w]||0)+1;});
    var rows=Object.keys(map).map(function(k){return [k,map[k]];}).sort(function(a,b){return b[1]-a[1]||(a[0]<b[0]?-1:1);}).slice(0,10);
    if(!rows.length){kw.innerHTML='<p class="hint">Type some text to see which words you use most often.</p>';return;}
    var max=rows[0][1];
    kw.innerHTML='<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Keyword</th><th>Count</th><th>Density</th><th style="width:35%"></th></tr></thead><tbody>'
      +rows.map(function(r){return '<tr><td>'+TH.esc(r[0])+'</td><td>'+r[1]+'</td><td>'+(r[1]/total*100).toFixed(1)+'%</td><td><span class="bar" style="width:'+Math.max(4,r[1]/max*100)+'%"></span></td></tr>';}).join('')
      +'</tbody></table></div>';
  }
  inp.addEventListener('input',calc);stop.addEventListener('change',calc);
  $('#wc-clear',root).addEventListener('click',function(){inp.value='';calc();inp.focus();});
  $('#wc-copy',root).addEventListener('click',function(){if(!inp.value){TH.toast('Nothing to copy yet');return;}TH.copy(inp.value,'Text copied');});
  $('#wc-sample',root).addEventListener('click',function(){inp.value='Good writing is clear, direct and easy to follow. Short sentences help readers keep pace. Longer sentences can add detail, but only when every word earns its place.\n\nA quick word count shows how long a piece is. Reading time shows how much attention it asks for. Keyword density shows which ideas the text keeps returning to.';calc();});
  $('#wc-paste',root).addEventListener('click',function(){
