      for(k2=0;k2<18;k2++){var c=bit(vb,k2),a=size-11+k2%3,b=Math.floor(k2/3);setFn(a,b,c);setFn(b,a,c);}
    }
    // place data codewords in zig-zag order
    var idx=0,right,vert,jj,x,y;
    for(right=size-1;right>=1;right-=2){
      if(right===6){right=5;}
      for(vert=0;vert<size;vert++){
        for(jj=0;jj<2;jj++){
          x=right-jj;var up=((right+1)&2)===0;y=up?size-1-vert:vert;
          if(!fn[y][x]&&idx<all.length*8){m[y][x]=bit(all[idx>>>3],7-(idx&7));idx++;}
        }
      }
    }
    function applyMask(mask){
      var xx,yy,inv;
      for(yy=0;yy<size;yy++){for(xx=0;xx<size;xx++){
        switch(mask){
          case 0:inv=(xx+yy)%2===0;break;
          case 1:inv=yy%2===0;break;
          case 2:inv=xx%3===0;break;
          case 3:inv=(xx+yy)%3===0;break;
          case 4:inv=(Math.floor(xx/3)+Math.floor(yy/2))%2===0;break;
          case 5:inv=xx*yy%2+xx*yy%3===0;break;
          case 6:inv=(xx*yy%2+xx*yy%3)%2===0;break;
          default:inv=((xx+yy)%2+xx*yy%3)%2===0;
        }
        if(!fn[yy][xx]&&inv){m[yy][xx]=!m[yy][xx];}
      }}
    }
    function penalty(){
      var r=0,a,b,run,s,q,pass,line;
      for(pass=0;pass<2;pass++){
        for(a=0;a<size;a++){
          line=[];for(b=0;b<size;b++){line.push(pass?m[b][a]:m[a][b]);}
          run=1;
          for(b=1;b<size;b++){if(line[b]===line[b-1]){run++;if(run===5){r+=3;}else if(run>5){r++;}}else{run=1;}}
          s=line.map(function(t){return t?'1':'0';}).join('');
          q=0;while((q=s.indexOf('10111010000',q))!==-1){r+=40;q++;}
          q=0;while((q=s.indexOf('00001011101',q))!==-1){r+=40;q++;}
