      for(a=0;a<size;a++){for(b=0;b<size;b++){if(m[a][b]){dark++;}if(a<size-1&&b<size-1&&m[a][b]===m[a][b+1]&&m[a][b]===m[a+1][b]&&m[a][b]===m[a+1][b+1]){r+=3;}}}
