   +'<div class="row"><div class="field"><label for="qr-fg">Code color</label><input type="color" id="qr-fg" value="#0F172A"></div><div class="field"><label for="qr-bg">Background</label><input type="color" id="qr-bg" value="#FFFFFF"></div></div>'
   +'</div>'
   +'<div id="qr-msg"></div>'
