  var ta=$('#qr-text',root),size=$('#qr-size',root),margin=$('#qr-margin',root),ecc=$('#qr-ecc',root),fg=$('#qr-fg',root),bg=$('#qr-bg',root),cv=$('#qr-cv',root),msg=$('#qr-msg',root),info=$('#qr-info',root);
  var cur=null;
  function lum(h){var n=parseInt(h.slice(1),16),c=[(n>>16)&255,(n>>8)&255,n&255].map(function(v){v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2];}
  function draw(){
    $('#qr-sizev',root).textContent=size.value;$('#qr-marginv',root).textContent=margin.value;
