    var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+cur.total+' '+cur.total+'" width="'+size.value+'" height="'+size.value+'" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="'+bg.value+'"/><path d="'+d+'" fill="'+fg.value+'"/></svg>';
    TH.saveBlob(new Blob([svg],{type:'image/svg+xml'}),'qr-code.svg');
  });
