    else{var ft=parseFloat($('#bm-ft',root).value),inch=parseFloat($('#bm-in',root).value)||0;h=(ft*12+inch)*0.0254;w=parseFloat($('#bm-lb',root).value)*0.45359237;}
    if(!(h>0)||!(w>0)){res.hidden=true;if(strict){msg.innerHTML='<div class="msg err">Please enter both height and weight as positive numbers.</div>';}return;}
    if(h<0.5||h>2.72||w<10||w>700){res.hidden=true;msg.innerHTML='<div class="msg err">Those values look unrealistic. Please check your height and weight.</div>';return;}
    var bmi=w/(h*h),c=CATS.filter(function(x){return bmi<x[0];})[0];
    var lo=18.5*h*h,hi=24.9*h*h,pos=Math.max(0,Math.min(100,(bmi-13)/(40-13)*100));
    var range=unit==='metric'?lo.toFixed(1)+' kg to '+hi.toFixed(1)+' kg':(lo/0.45359237).toFixed(1)+' lb to '+(hi/0.45359237).toFixed(1)+' lb';
    res.hidden=false;
    res.innerHTML='<div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-top:20px"><div class="big" style="color:'+c[2]+'">'+bmi.toFixed(1)+'</div><div><span class="pill" style="background:'+c[2]+'">'+c[1]+'</span><div class="hint" style="margin-top:6px">Body mass index (kg/m\u00B2)</div></div></div>'
     +'<div class="scale" aria-hidden="true"><i style="left:'+pos+'%"></i></div>'
     +'<div style="display:flex;justify-content:space-between;font-size:.8rem;color:var(--muted)"><span>13</span><span>18.5</span><span>25</span><span>30</span><span>40+</span></div>'
     +'<div class="stat" style="margin-top:18px"><span>Healthy weight range for your height (BMI 18.5 to 24.9)</span><b style="font-size:1.2rem">'+range+'</b></div>'
     +'<p class="hint" style="margin-top:14px">BMI is a screening measure, not a diagnosis. It does not separate muscle from fat, and it is not designed for children, pregnant women or competitive athletes. Speak to a doctor for personal advice.</p>';
  }
  tm.addEventListener('click',function(){setUnit('metric');});ti.addEventListener('click',function(){setUnit('imperial');});
  $$('input',root).forEach(function(i){i.addEventListener('input',function(){calc(false);});});
  $('#bm-go',root).addEventListener('click',function(){calc(true);});
  $('#bm-reset',root).addEventListener('click',function(){$$('input',root).forEach(function(i){i.value='';});msg.innerHTML='';res.hidden=true;});
 },
 art:{
  intro:[
