   weight:{n:'Weight',u:[['Milligram (mg)',0.000001],['Gram (g)',0.001],['Kilogram (kg)',1],['Tonne (t)',1000],['Ounce (oz)',0.028349523125],['Pound (lb)',0.45359237],['Stone (st)',6.35029318]],f:2,t:5},
