   speed:{n:'Speed',u:[['Meter/second (m/s)',1],['Kilometer/hour (km/h)',0.2777777777778],['Mile/hour (mph)',0.44704],['Knot (kn)',0.5144444444444],['Foot/second (ft/s)',0.3048]],f:1,t:2},
