(function(TH){try{
var $=TH.$,icon=TH.icon;
TH.add({
 slug:'json-formatter',name:'JSON Formatter',h1:'JSON Formatter & Validator',cat:'Developer',icon:'braces',
 short:'Beautify, minify and validate JSON, with clear error messages showing line and column.',
 kw:'json formatter validator beautify minify pretty print parse lint developer api sort keys',
 title:'JSON Formatter & Validator: Beautify, Minify and Fix JSON',
 desc:'Free online JSON formatter and validator. Beautify, minify and validate JSON with clear error messages that show the exact line and column. Runs in your browser.',
 render:function(root){
  root.innerHTML=
   '<div class="field"><label for="js-in">JSON input</label><textarea id="js-in" class="mono" style="min-height:220px" spellcheck="false" placeholder=\'Paste your JSON here, for example {"name":"Ali","age":30}\'></textarea></div>'
   +'<div class="row" style="align-items:center;margin-bottom:6px"><div class="field" style="max-width:190px;margin:0"><label for="js-ind">Indentation</label><select id="js-ind"><option value="2">2 spaces</option><option value="4">4 spaces</option><option value="tab">Tab</option></select></div><label class="chk" style="margin-top:22px"><input type="checkbox" id="js-sort"> Sort keys A to Z</label></div>'
   +'<div class="btn-row"><button class="btn btn-primary" type="button" id="js-beauty">Beautify</button><button class="btn" type="button" id="js-min">Minify</button><button class="btn" type="button" id="js-val">Validate</button><button class="btn" type="button" id="js-sample">Sample</button><button class="btn" type="button" id="js-clear">'+icon('trash')+'Clear</button></div>'
   +'<div id="js-msg" role="status"></div>'
   +'<div class="field" style="margin-top:16px"><label for="js-out">Result</label><textarea id="js-out" class="mono" style="min-height:220px" readonly spellcheck="false" placeholder="Formatted JSON appears here"></textarea></div>'
   +'<div class="btn-row" style="margin-top:0"><button class="btn btn-primary" type="button" id="js-copy">'+icon('copy')+'Copy result</button><button class="btn" type="button" id="js-dl">'+icon('download')+'Download .json</button><button class="btn" type="button" id="js-use">'+icon('swap')+'Use result as input</button></div>';
  var inp=$('#js-in',root),out=$('#js-out',root),msg=$('#js-msg',root),ind=$('#js-ind',root),sort=$('#js-sort',root);
  function lc(text,pos){var before=text.slice(0,pos),lines=before.split('\n');return {line:lines.length,col:lines[lines.length-1].length+1};}
  function sortDeep(v){
    if(Array.isArray(v)){return v.map(sortDeep);}
    if(v&&typeof v==='object'){var o={};Object.keys(v).sort().forEach(function(k){o[k]=sortDeep(v[k]);});return o;}
    return v;
  }
  function parse(){
    var t=inp.value;
    if(!t.trim()){msg.innerHTML='<div class="msg err">Please paste some JSON first.</div>';out.value='';return {ok:false};}
    try{return {ok:true,val:JSON.parse(t)};}
    catch(e){
      var m=String(e.message||e),pos=null,line=null,col=null,r;
      if((r=/line (\d+) column (\d+)/i.exec(m))){line=+r[1];col=+r[2];}
      else if((r=/position (\d+)/i.exec(m))){pos=+r[1];var x=lc(t,pos);line=x.line;col=x.col;}
      else if(/end of (json|data)|unexpected end/i.test(m)){var y=lc(t,t.length);line=y.line;col=y.col;}
      out.value='';
      var clean=m.replace(/\s*\(line \d+ column \d+\)/i,'').replace(/ in JSON at position \d+.*/i,'');
      msg.innerHTML='<div class="msg err"><strong>Invalid JSON.</strong> '+TH.esc(clean)+(line?' <br>Problem near <strong>line '+line+', column '+col+'</strong>.':'')+'</div>';
      if(line){
        var lines=t.split('\n'),start=0,i;for(i=0;i<line-1;i++){start+=lines[i].length+1;}
        try{inp.focus();inp.setSelectionRange(start+col-1,start+col);}catch(e2){}
      }
      return {ok:false};
    }
  }
  function indent(){return ind.value==='tab'?'\t':+ind.value;}
  function prep(v){return sort.checked?sortDeep(v):v;}
  $('#js-beauty',root).addEventListener('click',function(){var p=parse();if(!p.ok){return;}out.value=JSON.stringify(prep(p.val),null,indent());msg.innerHTML='<div class="msg ok">Valid JSON. Formatted successfully.</div>';});
  $('#js-min',root).addEventListener('click',function(){var p=parse();if(!p.ok){return;}out.value=JSON.stringify(prep(p.val));var s=inp.value.length-out.value.length;msg.innerHTML='<div class="msg ok">Valid JSON. Minified'+(s>0?' and saved '+TH.fmt(s,0)+' characters':'')+'.</div>';});
  $('#js-val',root).addEventListener('click',function(){var p=parse();if(!p.ok){return;}var t=Array.isArray(p.val)?'array with '+p.val.length+' item'+(p.val.length===1?'':'s'):(p.val&&typeof p.val==='object'?'object with '+Object.keys(p.val).length+' key'+(Object.keys(p.val).length===1?'':'s'):typeof p.val);msg.innerHTML='<div class="msg ok">Valid JSON: '+t+'.</div>';});
  $('#js-sample',root).addEventListener('click',function(){inp.value='{"site":"Online Tools","free":true,"tools":[{"name":"Word Counter","id":1},{"name":"QR Code Generator","id":4}],"contact":{"email":"hello@example.com","languages":["en","ur"]},"rating":4.8,"notes":null}';msg.innerHTML='';out.value='';});
  $('#js-clear',root).addEventListener('click',function(){inp.value='';out.value='';msg.innerHTML='';inp.focus();});
  $('#js-copy',root).addEventListener('click',function(){if(!out.value){TH.toast('Nothing to copy yet. Beautify or minify first.');return;}TH.copy(out.value,'JSON copied');});
  $('#js-dl',root).addEventListener('click',function(){if(!out.value){TH.toast('Nothing to download yet');return;}TH.saveBlob(new Blob([out.value],{type:'application/json'}),'data.json');});
  $('#js-use',root).addEventListener('click',function(){if(!out.value){TH.toast('Nothing to move yet');return;}inp.value=out.value;out.value='';msg.innerHTML='';});
 },
 art:{
  intro:[
   'The JSON Formatter &amp; Validator turns messy or minified JSON into clean, readable, indented text, and checks that it is valid at the same time. When something is wrong, it does not just say &ldquo;error&rdquo;. It tells you what the parser found and points to the line and column so you can fix the problem quickly.',
   'JSON is the everyday data format of web APIs, configuration files and databases, but a single missing comma or an extra quote can break an entire application. Beautifying makes structure easy to scan, while minifying strips whitespace to make payloads smaller. Because everything runs locally in your browser, you can safely paste API responses and configuration data without exposing them to a third-party server.'
