var $=TH.$,icon=TH.icon;
TH.add({
 slug:'image-compressor',name:'Image Compressor',h1:'Image Compressor',cat:'Design & Media',icon:'image',
 short:'Reduce JPG, PNG and WebP file size right in your browser, with before and after comparison.',
 kw:'image compressor compress photo jpg jpeg png webp reduce size resize optimize picture kb mb',
 title:'Image Compressor: Reduce JPG, PNG & WebP Size Online',
 desc:'Free image compressor. Shrink JPG, PNG and WebP photos with a quality slider and see before and after sizes. Files are processed in your browser and never uploaded.',
 render:function(root){
  root.innerHTML=
   '<div class="drop" id="ic-drop" tabindex="0" role="button" aria-label="Choose an image to compress">'+icon('upload')+'<p style="margin:0"><strong>Click to choose an image</strong> or drag and drop it here</p><p class="hint" style="margin:6px 0 0">JPG, PNG or WebP. Processed on your device only.</p></div>'
   +'<input type="file" id="ic-file" accept="image/jpeg,image/png,image/webp" hidden>'
   +'<div id="ic-msg"></div>'
   +'<div id="ic-panel" hidden style="margin-top:20px">'
   +'<div class="grid3">'
   +'<div class="field"><label for="ic-q">Quality: <b id="ic-qv">75</b>%</label><input type="range" id="ic-q" min="10" max="100" value="75"></div>'
   +'<div class="field"><label for="ic-fmt">Output format</label><select id="ic-fmt"><option value="image/jpeg">JPEG (smallest for photos)</option><option value="image/webp">WebP (modern, small)</option><option value="image/png">PNG (lossless)</option></select></div>'
   +'<div class="field"><label for="ic-w">Maximum width</label><select id="ic-w"><option value="0">Original size</option><option value="3840">3840 px</option><option value="1920">1920 px</option><option value="1280">1280 px</option><option value="1024">1024 px</option><option value="800">800 px</option><option value="500">500 px</option></select></div></div>'
   +'<p class="hint" id="ic-note" style="margin:0"></p>'
   +'<div class="stats" id="ic-stats"></div>'
   +'<div class="cmp"><figure><img id="ic-a" alt="Original image preview"><figcaption>Original <span id="ic-as"></span></figcaption></figure><figure><img id="ic-b" alt="Compressed image preview"><figcaption>Compressed <span id="ic-bs"></span></figcaption></figure></div>'
   +'<div class="btn-row"><button class="btn btn-primary" type="button" id="ic-dl">'+icon('download')+'Download compressed image</button><button class="btn" type="button" id="ic-new">'+icon('refresh')+'Choose another image</button></div></div>';
  var drop=$('#ic-drop',root),file=$('#ic-file',root),msg=$('#ic-msg',root),panel=$('#ic-panel',root),q=$('#ic-q',root),fmt=$('#ic-fmt',root),wsel=$('#ic-w',root);
  var img=null,orig=null,srcUrl=null,outUrl=null,outBlob=null,job=0,name='image';
  function revoke(){if(srcUrl){URL.revokeObjectURL(srcUrl);srcUrl=null;}if(outUrl){URL.revokeObjectURL(outUrl);outUrl=null;}}
  TH.onLeave(function(){job++;revoke();});
  function load(f){
    msg.innerHTML='';
    if(!f){return;}
    if(!/^image\/(jpeg|png|webp)$/.test(f.type)){msg.innerHTML='<div class="msg err">Please choose a JPG, PNG or WebP image.</div>';return;}
    if(f.size>50*1048576){msg.innerHTML='<div class="msg err">This file is larger than 50 MB. Please choose a smaller image.</div>';return;}
    revoke();orig=f;name=f.name.replace(/\.[^.]+$/,'')||'image';srcUrl=URL.createObjectURL(f);
    var im=new Image();
    im.onload=function(){img=im;$('#ic-a',root).src=srcUrl;$('#ic-as',root).textContent=TH.bytes(f.size)+' \u00B7 '+im.naturalWidth+'\u00D7'+im.naturalHeight;
      fmt.value=f.type==='image/png'?'image/png':(f.type==='image/webp'?'image/webp':'image/jpeg');panel.hidden=false;compress();};
    im.onerror=function(){msg.innerHTML='<div class="msg err">This image could not be read. It may be damaged or in an unsupported format.</div>';panel.hidden=true;};
    im.src=srcUrl;
  }
  function compress(){
    if(!img){return;}
    var my=++job,mw=+wsel.value,w=img.naturalWidth,h=img.naturalHeight;
    if(mw&&w>mw){h=Math.round(h*mw/w);w=mw;}
    var cv=document.createElement('canvas');cv.width=w;cv.height=h;
    var ctx=cv.getContext('2d');
    if(fmt.value==='image/jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);}
    ctx.drawImage(img,0,0,w,h);
    $('#ic-qv',root).textContent=q.value;
    $('#ic-note',root).textContent=fmt.value==='image/png'?'PNG is lossless, so the quality slider has no effect. Use a smaller maximum width or choose JPEG or WebP to reduce size.':'';
    cv.toBlob(function(b){
      if(my!==job){return;}
      if(!b){msg.innerHTML='<div class="msg err">Compression failed in this browser. Try a different format.</div>';return;}
      if(b.type!==fmt.value){msg.innerHTML='<div class="msg err">Your browser cannot create '+fmt.value.replace('image/','').toUpperCase()+' files, so '+b.type.replace('image/','').toUpperCase()+' was used instead.</div>';}else{msg.innerHTML='';}
      if(outUrl){URL.revokeObjectURL(outUrl);}
      outBlob=b;outUrl=URL.createObjectURL(b);
      $('#ic-b',root).src=outUrl;$('#ic-bs',root).textContent=TH.bytes(b.size)+' \u00B7 '+w+'\u00D7'+h;
      var saved=orig.size-b.size,pct=Math.round(saved/orig.size*100);
      $('#ic-stats',root).innerHTML='<div class="stat"><b>'+TH.bytes(orig.size)+'</b><span>Original size</span></div><div class="stat"><b>'+TH.bytes(b.size)+'</b><span>New size</span></div><div class="stat"><b style="color:'+(saved>0?'var(--ok)':'var(--err)')+'">'+(saved>0?'-':'+')+Math.abs(pct)+'%</b><span>'+(saved>0?'Saved '+TH.bytes(saved):'Larger than the original')+'</span></div>';
      if(saved<=0){msg.innerHTML+='<div class="msg err">The result is not smaller than the original. Lower the quality, reduce the maximum width or choose JPEG or WebP.</div>';}
    },fmt.value,+q.value/100);
  }
  drop.addEventListener('click',function(){file.click();});
  drop.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();file.click();}});
  file.addEventListener('change',function(){load(file.files[0]);file.value='';});
  ['dragenter','dragover'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.add('over');});});
  ['dragleave','drop'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.remove('over');});});
  drop.addEventListener('drop',function(e){var f=e.dataTransfer&&e.dataTransfer.files[0];load(f);});
  q.addEventListener('input',TH.debounce(compress,120));
  q.addEventListener('input',function(){$('#ic-qv',root).textContent=q.value;});
  fmt.addEventListener('change',compress);wsel.addEventListener('change',compress);
  $('#ic-dl',root).addEventListener('click',function(){
    if(!outBlob){TH.toast('Choose an image first');return;}
    var ext=outBlob.type==='image/png'?'png':(outBlob.type==='image/webp'?'webp':'jpg');
    TH.saveBlob(outBlob,name+'-compressed.'+ext);
  });
  $('#ic-new',root).addEventListener('click',function(){file.click();});
 },
 art:{
  intro:[
   'The Image Compressor reduces the file size of JPG, PNG and WebP pictures without leaving your browser. Drop in a photo, move the quality slider, optionally shrink the maximum width and compare the original with the compressed version side by side, along with the exact number of kilobytes or megabytes saved.',
   'Large images slow down websites, fill up email attachments and eat storage space. Compressing them makes pages load faster, which helps visitors and search rankings, and makes files small enough for upload forms with strict limits. Many online compressors upload your pictures to a remote server. This one does all the work on your own device using the browser&rsquo;s built-in canvas, so private photos, ID scans and client images are never sent anywhere.'
  ],
  steps:[
   'Click the upload area to choose a picture, or drag and drop an image onto it. JPG, PNG and WebP files are supported.',
   'Move the <strong>Quality</strong> slider. Values between 60 and 80 usually give a big size reduction with little visible loss.',
   'Optionally choose a <strong>Maximum width</strong> to resize large photos, and pick an <strong>Output format</strong>. JPEG and WebP compress photos best.',
   'Compare the two previews and check the sizes and percentage saved in the summary boxes.',
   'Press <strong>Download compressed image</strong> to save the file, or choose another image to start again.'
  ],
  features:[
   'Adjustable quality from 10% to 100% with instant re-compression.',
   'Output as JPEG, WebP or PNG, and resizing to common widths.',
   'Before and after previews with original and new sizes and pixel dimensions.',
   'Clear warnings when the result would be larger than the original.',
   'Drag and drop, keyboard access and mobile-friendly file picking.',
   'Nothing is uploaded, so it is safe for private images.'
  ],
  uses:[
   'Preparing photos for a website, blog or online store so pages load quickly.',
   'Shrinking pictures to fit email or form upload limits, such as 100 KB or 1 MB.',
   'Saving phone storage by reducing large camera photos.',
   'Converting heavy PNG screenshots to lighter JPEG or WebP files.',
   'Creating smaller thumbnails and social media images.'
  ],
  faqs:[
   ['Will compression reduce the quality of my image?','JPEG and WebP use lossy compression, so lowering the quality trades some detail for a smaller file. At around 70 to 80 percent the difference is rarely noticeable. PNG stays lossless.'],
   ['Why did my PNG barely get smaller?','PNG is a lossless format, so the quality slider does not apply. To reduce a PNG, lower the maximum width or convert it to JPEG or WebP if you do not need transparency.'],
   ['What happens to transparent backgrounds?','Transparency is kept for PNG and WebP. JPEG does not support it, so transparent areas are filled with white when you choose JPEG.'],
   ['Is there a limit on the file size?','Files up to 50 MB are accepted. Very large photos may take a moment to process because your device does the work.'],
   ['Are my images uploaded to your server?','No. The image is decoded and re-encoded locally using your browser&rsquo;s canvas. It never leaves your device, and the preview is removed when you leave the page.']
  ]
 }
});
}catch(e){if(window.console){console.error(e);}}})(window.TH);

