(function(TH){try{
var $=TH.$,$$=TH.$$,icon=TH.icon;
TH.add({
 slug:'color-picker',name:'Color Picker',h1:'Color Picker & Converter',cat:'Design & Media',icon:'drop',
 short:'Pick a color and convert between HEX, RGB, HSL and CMYK, with palettes and contrast checks.',
 kw:'color picker converter hex rgb hsl cmyk palette shades contrast wcag css design',
 title:'Color Picker & Converter: HEX, RGB, HSL and CMYK',
 desc:'Free color picker and converter. Choose any color and get HEX, RGB, HSL and CMYK codes instantly, with shades, harmonies and a WCAG contrast check.',
 render:function(root){
  root.innerHTML=
   '<div class="swatch" id="cp-sw" role="img" aria-label="Selected color preview" style="display:flex;align-items:flex-end;padding:12px;font-weight:700;font-family:var(--mono)"></div>'
   +'<div class="row" style="margin-bottom:6px"><div class="field" style="flex:0 0 auto"><label for="cp-pick">Pick</label><input type="color" id="cp-pick" value="#2563eb"></div>'
   +'<div class="field"><label for="cp-hex">HEX</label><input type="text" id="cp-hex" value="#2563EB" maxlength="7" spellcheck="false" autocomplete="off"></div>'
   +'<div class="field" style="flex:0 0 auto"><button class="btn" type="button" id="cp-rand">'+icon('refresh')+'Random</button></div>'
   +'<div class="field" style="flex:0 0 auto" id="cp-eye-w" hidden><button class="btn" type="button" id="cp-eye">'+icon('pipette')+'Pick from screen</button></div></div>'
   +'<div id="cp-msg"></div>'
   +'<div class="grid2"><fieldset style="border:0;padding:0;margin:0"><legend class="lbl" style="margin-bottom:6px">RGB</legend><div class="grid3">'
   +'<div class="field"><label for="cp-r" class="hint">R (0-255)</label><input type="number" id="cp-r" min="0" max="255" step="1"></div>'
   +'<div class="field"><label for="cp-g" class="hint">G (0-255)</label><input type="number" id="cp-g" min="0" max="255" step="1"></div>'
   +'<div class="field"><label for="cp-b" class="hint">B (0-255)</label><input type="number" id="cp-b" min="0" max="255" step="1"></div></div></fieldset>'
   +'<fieldset style="border:0;padding:0;margin:0"><legend class="lbl" style="margin-bottom:6px">HSL</legend><div class="grid3">'
   +'<div class="field"><label for="cp-h" class="hint">H (0-360)</label><input type="number" id="cp-h" min="0" max="360" step="1"></div>'
   +'<div class="field"><label for="cp-s" class="hint">S (0-100)</label><input type="number" id="cp-s" min="0" max="100" step="1"></div>'
   +'<div class="field"><label for="cp-l" class="hint">L (0-100)</label><input type="number" id="cp-l" min="0" max="100" step="1"></div></div></fieldset></div>'
   +'<h2 style="font-size:1.1rem;margin:14px 0 4px">Color codes</h2><div id="cp-codes"></div>'
   +'<h2 style="font-size:1.1rem;margin:22px 0 8px">Contrast (WCAG)</h2><div class="grid2" id="cp-con"></div>'
   +'<h2 style="font-size:1.1rem;margin:22px 0 8px">Shades and tints</h2><div class="palette" id="cp-shades"></div>'
   +'<h2 style="font-size:1.1rem;margin:22px 0 8px">Harmonies</h2><div id="cp-harm"></div>';
  var R=0,G=0,B=0;
  var pick=$('#cp-pick',root),hex=$('#cp-hex',root),msg=$('#cp-msg',root),sw=$('#cp-sw',root);
  var ids={r:$('#cp-r',root),g:$('#cp-g',root),b:$('#cp-b',root),h:$('#cp-h',root),s:$('#cp-s',root),l:$('#cp-l',root)};
  function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
  function h2(n){var s=Math.round(n).toString(16);return s.length<2?'0'+s:s;}
  function toHex(r,g,b){return ('#'+h2(r)+h2(g)+h2(b)).toUpperCase();}
  function parseHex(s){s=s.trim().replace(/^#/,'');if(/^[0-9a-f]{3}$/i.test(s)){s=s.replace(/./g,'$&$&');}if(!/^[0-9a-f]{6}$/i.test(s)){return null;}var n=parseInt(s,16);return [(n>>16)&255,(n>>8)&255,n&255];}
  function rgb2hsl(r,g,b){
    r/=255;g/=255;b/=255;var mx=Math.max(r,g,b),mn=Math.min(r,g,b),h=0,s=0,l=(mx+mn)/2,d=mx-mn;
    if(d){s=l>0.5?d/(2-mx-mn):d/(mx+mn);if(mx===r){h=(g-b)/d+(g<b?6:0);}else if(mx===g){h=(b-r)/d+2;}else{h=(r-g)/d+4;}h*=60;}
    return [Math.round(h)%360,Math.round(s*100),Math.round(l*100)];
  }
  function hsl2rgb(h,s,l){
    h=((h%360)+360)%360;s/=100;l/=100;
    var c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2,r=0,g=0,b=0;
    if(h<60){r=c;g=x;}else if(h<120){r=x;g=c;}else if(h<180){g=c;b=x;}else if(h<240){g=x;b=c;}else if(h<300){r=x;b=c;}else{r=c;b=x;}
    return [Math.round((r+m)*255),Math.round((g+m)*255),Math.round((b+m)*255)];
  }
  function cmyk(r,g,b){
    r/=255;g/=255;b/=255;var k=1-Math.max(r,g,b);if(k>=1){return [0,0,0,100];}
    return [Math.round((1-r-k)/(1-k)*100),Math.round((1-g-k)/(1-k)*100),Math.round((1-b-k)/(1-k)*100),Math.round(k*100)];
  }
  function lum(r,g,b){var a=[r,g,b].map(function(v){v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);});return 0.2126*a[0]+0.7152*a[1]+0.0722*a[2];}
  function ratio(l1,l2){return (Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05);}
  function set(r,g,b,src){
    R=clamp(Math.round(r),0,255);G=clamp(Math.round(g),0,255);B=clamp(Math.round(b),0,255);
    var hx=toHex(R,G,B),hsl=rgb2hsl(R,G,B),cm=cmyk(R,G,B);
    msg.innerHTML='';
    if(src!=='hex'){hex.value=hx;}
    pick.value=hx.toLowerCase();
    if(src!=='rgb'){ids.r.value=R;ids.g.value=G;ids.b.value=B;}
    if(src!=='hsl'){ids.h.value=hsl[0];ids.s.value=hsl[1];ids.l.value=hsl[2];}
    var L=lum(R,G,B);
    sw.style.background=hx;sw.style.color=L>0.4?'#0F172A':'#FFFFFF';sw.textContent=hx;
    var codes=[['HEX',hx],['RGB','rgb('+R+', '+G+', '+B+')'],['HSL','hsl('+hsl[0]+', '+hsl[1]+'%, '+hsl[2]+'%)'],['CMYK','cmyk('+cm[0]+'%, '+cm[1]+'%, '+cm[2]+'%, '+cm[3]+'%)'],['CSS','--color: '+hx+';']];
    $('#cp-codes',root).innerHTML=codes.map(function(c,i){return '<div class="vrow"><b>'+c[0]+'</b><code>'+TH.esc(c[1])+'</code><button class="btn btn-sm" type="button" data-i="'+i+'">Copy</button></div>';}).join('');
    $$('#cp-codes button',root).forEach(function(b){b.addEventListener('click',function(){TH.copy(codes[+b.getAttribute('data-i')][1],codes[+b.getAttribute('data-i')][0]+' copied');});});
    var cw=ratio(L,1),cb=ratio(L,0);
    function cell(label,r,txt,bg){var aa=r>=4.5,aaa=r>=7,big=r>=3;return '<div class="stat" style="background:'+bg+';color:'+txt+'"><b style="color:'+txt+'">'+r.toFixed(2)+':1</b><span style="color:'+txt+'">'+label+' &middot; '+(aaa?'AAA pass':aa?'AA pass':big?'Large text only':'Fails')+'</span></div>';}
    $('#cp-con',root).innerHTML=cell('Color on white text',cw,'#FFFFFF',hx)+cell('Color on black text',cb,'#000000',hx);
    var sh='';
    [95,85,75,65,55,45,35,25,15,8].forEach(function(l){var c=hsl2rgb(hsl[0],hsl[1],l),x=toHex(c[0],c[1],c[2]);sh+='<button type="button" style="background:'+x+'" data-c="'+x+'" aria-label="Use '+x+'" title="'+x+'"></button>';});
    $('#cp-shades',root).innerHTML=sh;
    var H=[['Complementary',[180]],['Triadic',[120,240]],['Analogous',[-30,30]],['Split complementary',[150,210]]];
    $('#cp-harm',root).innerHTML=H.map(function(g){
      var btns='<button type="button" style="background:'+hx+'" data-c="'+hx+'" aria-label="Use '+hx+'" title="'+hx+'"></button>'+g[1].map(function(d){var c=hsl2rgb(hsl[0]+d,hsl[1],hsl[2]),x=toHex(c[0],c[1],c[2]);return '<button type="button" style="background:'+x+'" data-c="'+x+'" aria-label="Use '+x+'" title="'+x+'"></button>';}).join('');
      return '<div style="margin-bottom:12px"><div class="hint" style="margin-bottom:4px">'+g[0]+'</div><div class="palette">'+btns+'</div></div>';
    }).join('');
    $$('.palette button',root).forEach(function(b){b.addEventListener('click',function(){var c=parseHex(b.getAttribute('data-c'));set(c[0],c[1],c[2]);});});
  }
  hex.addEventListener('input',function(){
    var c=parseHex(hex.value);
    if(c){set(c[0],c[1],c[2],'hex');hex.removeAttribute('aria-invalid');}
    else{hex.setAttribute('aria-invalid','true');msg.innerHTML='<div class="msg err">Enter a valid HEX color such as #2563EB or #26E.</div>';}
  });
  pick.addEventListener('input',function(){var c=parseHex(pick.value);set(c[0],c[1],c[2]);});
  ['r','g','b'].forEach(function(k){ids[k].addEventListener('input',function(){
