    var c=hsl2rgb(clamp(+ids.h.value||0,0,360),clamp(+ids.s.value||0,0,100),clamp(+ids.l.value||0,0,100));set(c[0],c[1],c[2],'hsl');
  });});
  $('#cp-rand',root).addEventListener('click',function(){set(Math.random()*256,Math.random()*256,Math.random()*256);});
  if(window.EyeDropper){
    $('#cp-eye-w',root).hidden=false;
    $('#cp-eye',root).addEventListener('click',function(){new window.EyeDropper().open().then(function(r){var c=parseHex(r.sRGBHex);if(c){set(c[0],c[1],c[2]);}}).catch(function(){});});
  }
  set(37,99,235);
 },
 art:{
  intro:[
   'The Color Picker &amp; Converter lets you choose any color and instantly see it written in the formats designers and developers use every day: HEX, RGB, HSL and CMYK. Type a code, drag the RGB or HSL values, use the visual picker or grab a color from anywhere on your screen, and every other format updates at once.',
   'Beyond simple conversion, the tool builds a palette of shades and tints, suggests harmonious color combinations and checks contrast against white and black text using the WCAG accessibility ratios. That makes it easy to choose readable text colors, build a consistent brand palette and copy ready-to-use values for CSS, design software or print. All calculations happen in your browser, so nothing is uploaded and there is nothing to install.'
  ],
  steps:[
   'Click the color square to open your system picker, or type a value into the <strong>HEX</strong> box. Short codes such as #26E are accepted.',
   'Fine-tune the color with the <strong>RGB</strong> or <strong>HSL</strong> number boxes. The preview and every other format update immediately.',
   'On supported browsers, press <strong>Pick from screen</strong> to sample any color visible on your display. Press <strong>Random</strong> for inspiration.',
   'Press <strong>Copy</strong> next to the HEX, RGB, HSL, CMYK or CSS value you need.',
   'Click any swatch under <strong>Shades and tints</strong> or <strong>Harmonies</strong> to make it your current color, and check the contrast boxes before using it for text.'
  ],
  features:[
   'Live two-way conversion between HEX, RGB, HSL and CMYK.',
   'Large preview swatch with an automatically readable label.',
   'WCAG contrast ratios against white and black, with AA and AAA results.',
   'Ten-step shade and tint palette generated from your color.',
   'Complementary, triadic, analogous and split-complementary harmonies.',
   'Copy buttons for every format, plus an optional on-screen eyedropper.'
  ],
  uses:[
   'Converting a brand HEX code to RGB or HSL for a stylesheet or design tool.',
   'Choosing text and background colors that meet accessibility guidelines.',
   'Building a palette of lighter and darker variants for buttons and hover states.',
   'Finding matching accent colors for a website, logo or presentation.',
   'Translating screen colors into approximate CMYK values for print briefs.'
  ],
  faqs:[
   ['What is the difference between HEX, RGB and HSL?','They describe the same color in different ways. HEX is a compact code such as #2563EB, RGB gives red, green and blue amounts from 0 to 255, and HSL describes hue, saturation and lightness, which is often easier to adjust by hand.'],
   ['Are the CMYK values exact?','No. CMYK is converted with a standard mathematical formula and does not include a printer profile. Real printed colors depend on ink, paper and color management, so treat CMYK here as an approximation.'],
   ['What contrast ratio do I need for readable text?','WCAG asks for at least 4.5 to 1 for normal text at level AA, 3 to 1 for large text and 7 to 1 for the stricter AAA level. The tool shows how your color performs against white and black.'],
   ['Why is the Pick from screen button missing?','It relies on the EyeDropper feature, which is currently available in Chromium-based browsers such as Chrome and Edge on desktop. You can still use the picker, HEX, RGB and HSL inputs everywhere.'],
   ['Does the tool save the colors I choose?','No. Everything is calculated locally in your browser and forgotten when you close the page. Copy any values you want to keep.']
  ]
 }
});
}catch(e){if(window.console){console.error(e);}}})(window.TH);

