/* =====================================================================
   TOOLS 11-14: PDF SUITE  (Merge, Split/Extract, Rotate, Images to PDF)
   Uses pdf-lib, loaded from CDN only when a visitor opens one of these
   tools, so pages that do not need it stay fast. Nothing is uploaded;
   pdf-lib runs entirely inside the browser.
   ===================================================================== */
(function(TH){try{
var $=TH.$,$$=TH.$$,icon=TH.icon;

/* ---------- shared: lazy-load pdf-lib once, reused by all 4 tools ---------- */
var PDFLIB_URL='https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js';
var pdfLibPromise=null;
function loadPdfLib(){
 if(window.PDFLib){return Promise.resolve(window.PDFLib);}
 if(pdfLibPromise){return pdfLibPromise;}
 pdfLibPromise=new Promise(function(resolve,reject){
  var s=document.createElement('script');
  s.src=PDFLIB_URL;s.async=true;
  s.onload=function(){window.PDFLib?resolve(window.PDFLib):reject(new Error('load'));};
  s.onerror=function(){pdfLibPromise=null;reject(new Error('load'));};
  document.head.appendChild(s);
 });
 return pdfLibPromise;
}
function loadFailMsg(){return '<div class="msg err">The PDF engine could not be loaded. Check your internet connection and try again.</div>';}

/* ---------- shared: parse a page list like "1-3,5,8-10" into 0-based indices ---------- */
function parsePageRange(s,max){
 var out=[],seen={},parts=String(s).split(',');
 for(var i=0;i<parts.length;i++){
  var p=parts[i].trim();if(!p){continue;}
  var m=/^(\d+)\s*-\s*(\d+)$/.exec(p);
  if(m){
   var a=+m[1],b=+m[2];if(a>b){var t=a;a=b;b=t;}
   for(var n=a;n<=b;n++){if(n>=1&&n<=max&&!seen[n]){seen[n]=1;out.push(n-1);}}
  }else if(/^\d+$/.test(p)){
   var n2=+p;if(n2>=1&&n2<=max&&!seen[n2]){seen[n2]=1;out.push(n2-1);}
  }else{return null;}
 }
 return out;
}
function allIndices(n){var a=[];for(var i=0;i<n;i++){a.push(i);}return a;}

/* ---------- shared: draggable-free reorderable file list (used by merge & jpg-to-pdf) ---------- */
function makeFileList(listEl,onChange){
 var files=[],uid=0;
 function paint(){
  listEl.innerHTML=files.map(function(f,i){
   return '<div class="frow" data-id="'+f.id+'">'+icon('file')+'<span class="fname">'+TH.esc(f.file.name)+'</span><span class="fsize">'+TH.bytes(f.file.size)+'</span>'
    +'<span class="fbtns">'
    +'<button type="button" data-act="up" '+(i===0?'disabled':'')+' aria-label="Move up">\u2191</button>'
    +'<button type="button" data-act="down" '+(i===files.length-1?'disabled':'')+' aria-label="Move down">\u2193</button>'
    +'<button type="button" data-act="rm" aria-label="Remove">'+icon('trash')+'</button>'
    +'</span></div>';
  }).join('');
  onChange(files);
 }
 listEl.addEventListener('click',function(e){
  var b=e.target.closest('button[data-act]');if(!b){return;}
  var row=b.closest('.frow'),id=+row.getAttribute('data-id'),idx=-1;
  for(var i=0;i<files.length;i++){if(files[i].id===id){idx=i;break;}}
  if(idx<0){return;}
  var act=b.getAttribute('data-act');
  if(act==='rm'){files.splice(idx,1);}
  else if(act==='up'&&idx>0){var t=files[idx-1];files[idx-1]=files[idx];files[idx]=t;}
  else if(act==='down'&&idx<files.length-1){var t2=files[idx+1];files[idx+1]=files[idx];files[idx]=t2;}
  paint();
 });
 return {
  add:function(list0,accept,maxBytes){
   var rejected=[];
   Array.prototype.slice.call(list0).forEach(function(f){
    if(accept&&!accept(f)){rejected.push(f.name);return;}
    if(maxBytes&&f.size>maxBytes){rejected.push(f.name);return;}
    files.push({id:++uid,file:f});
   });
   paint();
   return rejected;
  },
  clear:function(){files=[];paint();},
  get:function(){return files;}
 };
}

/* ===================================================================
   TOOL 11: MERGE PDF
   =================================================================== */
TH.add({
 slug:'merge-pdf',name:'Merge PDF',h1:'Merge PDF Files',cat:'PDF & Files',icon:'layers',
 short:'Combine two or more PDF files into a single document, in the order you choose.',
 kw:'merge pdf combine pdf join pdf files pdf merger online free',
 title:'Merge PDF: Combine Multiple PDF Files Online Free',
 desc:'Free online tool to merge PDF files into one document. Reorder files before combining. Everything runs in your browser; files are never uploaded.',
 render:function(root){
  root.innerHTML=
   '<div class="drop" id="mg-drop" tabindex="0" role="button" aria-label="Choose PDF files to merge">'+icon('upload')+'<p style="margin:0"><strong>Click to choose PDF files</strong> or drag and drop them here</p><p class="hint" style="margin:6px 0 0">Add two or more PDF files. Processed on your device only.</p></div>'
   +'<input type="file" id="mg-file" accept="application/pdf" multiple hidden>'
   +'<div id="mg-msg"></div>'
   +'<div id="mg-list" class="flist"></div>'
   +'<div class="btn-row" id="mg-actions" hidden>'
   +'<button class="btn btn-primary" type="button" id="mg-go">'+icon('download')+'Merge &amp; download PDF</button>'
   +'<button class="btn" type="button" id="mg-clear">'+icon('trash')+'Clear all</button></div>';
  var drop=$('#mg-drop',root),file=$('#mg-file',root),msg=$('#mg-msg',root),listEl=$('#mg-list',root),actions=$('#mg-actions',root);
  var fl=makeFileList(listEl,function(files){actions.hidden=!files.length;});
  function isPdf(f){return f.type==='application/pdf'||/\.pdf$/i.test(f.name);}
  function addFiles(list0){
   msg.innerHTML='';
   var bad=fl.add(list0,isPdf,80*1048576);
   if(bad.length){msg.innerHTML='<div class="msg err">'+TH.esc(bad.join(', '))+' could not be added. Only PDF files up to 80 MB are supported.</div>';}
  }
  drop.addEventListener('click',function(){file.click();});
  drop.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();file.click();}});
  file.addEventListener('change',function(){addFiles(file.files);file.value='';});
  ['dragenter','dragover'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.add('over');});});
  ['dragleave','drop'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.remove('over');});});
  drop.addEventListener('drop',function(e){var f=e.dataTransfer&&e.dataTransfer.files;if(f&&f.length){addFiles(f);}});
  $('#mg-clear',root).addEventListener('click',function(){fl.clear();msg.innerHTML='';});
  $('#mg-go',root).addEventListener('click',function(){
   var files=fl.get();
   if(files.length<2){msg.innerHTML='<div class="msg err">Please add at least two PDF files to merge.</div>';return;}
   var btn=$('#mg-go',root);btn.disabled=true;btn.innerHTML='Merging&hellip;';
   msg.innerHTML='<div class="msg ok">Loading the PDF engine and merging your files&hellip;</div>';
   loadPdfLib().then(function(PDFLib){
    return PDFLib.PDFDocument.create().then(function(out){
     var chain=Promise.resolve();
     files.forEach(function(f){
      chain=chain.then(function(){
       return f.file.arrayBuffer().then(function(buf){
        return PDFLib.PDFDocument.load(buf,{ignoreEncryption:true}).then(function(src){
         return out.copyPages(src,src.getPageIndices()).then(function(pages){pages.forEach(function(p){out.addPage(p);});});
        }).catch(function(){throw new Error('bad:'+f.file.name);});
       });
      });
     });
     return chain.then(function(){return out.save();});
    });
   }).then(function(bytes){
    TH.saveBlob(new Blob([bytes],{type:'application/pdf'}),'merged.pdf');
    msg.innerHTML='<div class="msg ok">Merged '+files.length+' PDF files successfully. Your download has started.</div>';
   }).catch(function(e){
    var m=String(e&&e.message||'');
    msg.innerHTML=/^bad:/.test(m)?'<div class="msg err">'+TH.esc(m.slice(4))+' could not be read. It may be corrupted or password protected.</div>':loadFailMsg();
   }).then(function(){btn.disabled=false;btn.innerHTML=icon('download')+'Merge &amp; download PDF';});
  });
 },
 art:{
  intro:[
   'Merge PDF combines two or more PDF files into a single document, in whatever order you choose, without leaving your browser. Add your files, drag them into the right order with the up and down buttons, then download one combined PDF.',
   'Because everything runs locally using the open-source pdf-lib library, your documents are never uploaded to a server. This makes it a sensible choice for contracts, invoices, ID scans and other files you would rather keep private.'
  ],
  steps:[
   'Click the upload area to choose PDF files, or drag and drop several files onto it. You can add more files at any time.',
   'Use the <strong>&uarr;</strong> and <strong>&darr;</strong> buttons on each row to put the files in the order you want them to appear in the final document.',
   'Remove any file you do not need with the trash icon.',
   'Press <strong>Merge &amp; download PDF</strong>. The combined file downloads as <code>merged.pdf</code>.'
  ],
  features:[
   'Combine any number of PDF files into one.',
   'Reorder files before merging with simple up and down controls.',
   'Keeps the original page order within each file.',
   'Works entirely on your device; files are never uploaded.',
   'Clear error messages if a file is corrupted or password protected.'
  ],
  uses:[
   'Combining scanned pages or multiple contracts into a single document to send.',
   'Putting together a report from separate chapter PDFs.',
   'Merging invoices or statements before saving or printing.',
   'Joining a cover letter and a resume into one PDF for a job application.'
  ],
  faqs:[
   ['How many PDF files can I merge?','There is no fixed limit, but each file must be under 80 MB and your device needs enough memory to hold all files while merging. Most everyday documents merge in a second or two.'],
   ['Can I merge password-protected PDFs?','Files that are encrypted with an open password usually cannot be read by the browser and will show an error. Remove the password with your PDF reader first, then merge.'],
   ['Will merging change the page order inside each file?','No. Pages stay in their original order within each file. Only the order of the files themselves, which you control, changes.'],
   ['Are my files uploaded anywhere?','No. Merging happens locally in your browser using JavaScript. Your PDF files never leave your device.']
  ]
 }
});

