TH.add({
 slug:'split-pdf',name:'Split PDF',h1:'Split & Extract PDF Pages',cat:'PDF & Files',icon:'scissors',
 short:'Pull specific pages out of a PDF or split it into a smaller file, right in your browser.',
 kw:'split pdf pdf splitter extract pages from pdf pdf page extractor remove pages',
 title:'PDF Splitter: Extract or Split PDF Pages Online Free',
 desc:'Free online PDF splitter. Choose exactly which pages to keep, such as 1-3,5,8-10, and download a new PDF. Files are processed in your browser and never uploaded.',
 render:function(root){
  root.innerHTML=
   '<div class="drop" id="sp-drop" tabindex="0" role="button" aria-label="Choose a PDF file to split">'+icon('upload')+'<p style="margin:0"><strong>Click to choose a PDF file</strong> or drag and drop it here</p><p class="hint" style="margin:6px 0 0">One PDF at a time. Processed on your device only.</p></div>'
   +'<input type="file" id="sp-file" accept="application/pdf" hidden>'
   +'<div id="sp-msg"></div>'
   +'<div id="sp-panel" hidden style="margin-top:18px">'
   +'<p class="hint" id="sp-info"></p>'
   +'<div class="field"><label for="sp-range">Pages to keep</label><input type="text" id="sp-range" placeholder="e.g. 1-3,5,8-10"></div>'
   +'<p class="hint">Use commas for single pages and a dash for ranges, in any order &mdash; for example <code>1-3,5,8-10</code>.</p>'
   +'<div class="btn-row"><button class="btn btn-primary" type="button" id="sp-go">'+icon('download')+'Extract &amp; download PDF</button><button class="btn" type="button" id="sp-new">'+icon('refresh')+'Choose another PDF</button></div></div>';
  var drop=$('#sp-drop',root),file=$('#sp-file',root),msg=$('#sp-msg',root),panel=$('#sp-panel',root),info=$('#sp-info',root),range=$('#sp-range',root);
  var pdfDoc=null,pageCount=0,name='document';
  function load(f){
   msg.innerHTML='';panel.hidden=true;pdfDoc=null;
   if(!f){return;}
   if(f.type!=='application/pdf'&&!/\.pdf$/i.test(f.name)){msg.innerHTML='<div class="msg err">Please choose a PDF file.</div>';return;}
   if(f.size>100*1048576){msg.innerHTML='<div class="msg err">This file is larger than 100 MB. Please choose a smaller PDF.</div>';return;}
   name=f.name.replace(/\.pdf$/i,'')||'document';
   msg.innerHTML='<div class="msg ok">Loading the PDF engine&hellip;</div>';
   loadPdfLib().then(function(PDFLib){
    return f.arrayBuffer().then(function(buf){return PDFLib.PDFDocument.load(buf,{ignoreEncryption:true});});
   }).then(function(d){
    pdfDoc=d;pageCount=d.getPageCount();
    info.textContent='This PDF has '+pageCount+' page'+(pageCount===1?'':'s')+'.';
    range.value='1-'+pageCount;
    msg.innerHTML='';panel.hidden=false;
   }).catch(function(){
    msg.innerHTML='<div class="msg err">This PDF could not be read. It may be corrupted, password protected or not a valid PDF.</div>';
   });
  }
  drop.addEventListener('click',function(){file.click();});
  drop.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();file.click();}});
  file.addEventListener('change',function(){load(file.files[0]);file.value='';});
  ['dragenter','dragover'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.add('over');});});
  ['dragleave','drop'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.remove('over');});});
  drop.addEventListener('drop',function(e){load(e.dataTransfer&&e.dataTransfer.files[0]);});
  $('#sp-new',root).addEventListener('click',function(){file.click();});
  $('#sp-go',root).addEventListener('click',function(){
   if(!pdfDoc){return;}
   var idx=parsePageRange(range.value,pageCount);
   if(!idx||!idx.length){msg.innerHTML='<div class="msg err">Please enter a valid page list, for example 1-3,5,8-10.</div>';return;}
   var btn=$('#sp-go',root);btn.disabled=true;
   loadPdfLib().then(function(PDFLib){
    return PDFLib.PDFDocument.create().then(function(out){
     return out.copyPages(pdfDoc,idx).then(function(pages){pages.forEach(function(p){out.addPage(p);});return out.save();});
    });
   }).then(function(bytes){
    TH.saveBlob(new Blob([bytes],{type:'application/pdf'}),name+'-extract.pdf');
    msg.innerHTML='<div class="msg ok">Extracted '+idx.length+' page'+(idx.length===1?'':'s')+'. Your download has started.</div>';
   }).catch(function(){
    msg.innerHTML=loadFailMsg();
   }).then(function(){btn.disabled=false;});
  });
 },
 art:{
