  var drop=$('#jp-drop',root),file=$('#jp-file',root),msg=$('#jp-msg',root),listEl=$('#jp-list',root),opts=$('#jp-opts',root),actions=$('#jp-actions',root),fitSel=$('#jp-fit',root);
  var fl=makeFileList(listEl,function(files){opts.hidden=!files.length;actions.hidden=!files.length;});
  function isImg(f){return /^image\//.test(f.type);}
  function addFiles(list0){
   msg.innerHTML='';
   var bad=fl.add(list0,isImg,60*1048576);
