  $('#jp-clear',root).addEventListener('click',function(){fl.clear();msg.innerHTML='';});
  function prepImage(f,PDFLib,out){
   return f.arrayBuffer().then(function(buf){
    if(f.type==='image/jpeg'){return out.embedJpg(buf);}
    if(f.type==='image/png'){return out.embedPng(buf);}
    return new Promise(function(resolve,reject){
     var url=URL.createObjectURL(f);
     var im=new Image();
     im.onload=function(){
      var cv=document.createElement('canvas');cv.width=im.naturalWidth;cv.height=im.naturalHeight;
      cv.getContext('2d').drawImage(im,0,0);
      cv.toBlob(function(b){
       URL.revokeObjectURL(url);
       if(!b){reject(new Error('bad'));return;}
       b.arrayBuffer().then(function(buf2){out.embedPng(buf2).then(resolve,function(){reject(new Error('bad'));});});
      },'image/png');
     };
     im.onerror=function(){URL.revokeObjectURL(url);reject(new Error('bad'));};
     im.src=url;
    });
   }).catch(function(){throw new Error('bad:'+f.name);});
  }
  $('#jp-go',root).addEventListener('click',function(){
   var files=fl.get();
   if(files.length<1){msg.innerHTML='<div class="msg err">Please add at least one image.</div>';return;}
   var btn=$('#jp-go',root);btn.disabled=true;btn.innerHTML='Converting&hellip;';
   msg.innerHTML='<div class="msg ok">Loading the PDF engine and building your PDF&hellip;</div>';
   var fit=fitSel.value;
   loadPdfLib().then(function(PDFLib){
    return PDFLib.PDFDocument.create().then(function(out){
     var chain=Promise.resolve();
     files.forEach(function(f){
      chain=chain.then(function(){
       return prepImage(f.file,PDFLib,out).then(function(img){
        var iw=img.width,ih=img.height;
        if(fit==='orig'){
         var pg=out.addPage([iw,ih]);
         pg.drawImage(img,{x:0,y:0,width:iw,height:ih});
        }else{
         var landscape=iw>ih,pw=landscape?841.89:595.28,ph=landscape?595.28:841.89,margin=24;
         var mw=pw-margin*2,mh=ph-margin*2,scale=Math.min(mw/iw,mh/ih),dw=iw*scale,dh=ih*scale;
         var pg2=out.addPage([pw,ph]);
         pg2.drawImage(img,{x:(pw-dw)/2,y:(ph-dh)/2,width:dw,height:dh});
        }
       });
      });
     });
     return chain.then(function(){return out.save();});
    });
   }).then(function(bytes){
    TH.saveBlob(new Blob([bytes],{type:'application/pdf'}),'images.pdf');
    msg.innerHTML='<div class="msg ok">Created a PDF from '+files.length+' image'+(files.length===1?'':'s')+'. Your download has started.</div>';
   }).catch(function(e){
    var m=String(e&&e.message||'');
    msg.innerHTML=/^bad:/.test(m)?'<div class="msg err">'+TH.esc(m.slice(4))+' could not be read as an image.</div>':loadFailMsg();
   }).then(function(){btn.disabled=false;btn.innerHTML=icon('download')+'Create &amp; download PDF';});
  });
 },
 art:{
