   +'<div class="field"><label for="cp2-x">X</label><input type="number" id="cp2-x" min="0"></div>'
   +'<div class="field"><label for="cp2-y">Y</label><input type="number" id="cp2-y" min="0"></div>'
   +'<div class="field"><label for="cp2-w">Width</label><input type="number" id="cp2-w" min="1"></div>'
   +'<div class="field"><label for="cp2-h">Height</label><input type="number" id="cp2-h" min="1"></div></div>'
   +'<div class="btn-row"><button class="btn" type="button" id="cp2-center">Center crop box</button></div>'
   +'<div class="field" style="max-width:220px"><label for="cp2-fmt">Output format</label><select id="cp2-fmt"><option value="image/jpeg">JPEG</option><option value="image/png">PNG</option><option value="image/webp">WebP</option></select></div>'
   +'<div class="btn-row"><button class="btn btn-primary" type="button" id="cp2-go">'+icon('download')+'Crop &amp; download</button><button class="btn" type="button" id="cp2-new">'+icon('refresh')+'Choose another image</button></div></div>';
  var drop=$('#cp2-drop',root),file=$('#cp2-file',root),msg=$('#cp2-msg',root),panel=$('#cp2-panel',root);
  var wrap=$('#cp2-wrap',root),imgEl=$('#cp2-img',root),box=$('#cp2-box',root);
  var ratioSel=$('#cp2-ratio',root),xI=$('#cp2-x',root),yI=$('#cp2-y',root),wI2=$('#cp2-w',root),hI2=$('#cp2-h',root),fmtSel2=$('#cp2-fmt',root);
  var img=null,srcUrl=null,natW=0,natH=0,name='image';
  var cp={x:0,y:0,w:0,h:0};

  function revoke(){if(srcUrl){URL.revokeObjectURL(srcUrl);srcUrl=null;}}
  function ratioValue(){var v=ratioSel.value;if(v==='free'){return null;}var p=v.split(':');return (+p[0])/(+p[1]);}
  function dispScale(){return natW?wrap.clientWidth/natW:1;}
  function clampAll(ratio){
   if(ratio){
    var w=Math.max(1,Math.min(cp.w,natW,natH*ratio));
    cp.w=w;cp.h=w/ratio;
   }else{
    cp.w=Math.max(1,Math.min(cp.w,natW));
    cp.h=Math.max(1,Math.min(cp.h,natH));
   }
   cp.x=Math.max(0,Math.min(cp.x,natW-cp.w));
   cp.y=Math.max(0,Math.min(cp.y,natH-cp.h));
  }
  function paintBox(){
   var s=dispScale();
   box.style.left=(cp.x*s)+'px';box.style.top=(cp.y*s)+'px';
   box.style.width=(cp.w*s)+'px';box.style.height=(cp.h*s)+'px';
   xI.value=Math.round(cp.x);yI.value=Math.round(cp.y);
   wI2.value=Math.round(cp.w);hI2.value=Math.round(cp.h);
  }
  function centerBox(pct){
   pct=pct||0.7;var ratio=ratioValue(),w,h;
   if(ratio){
    if(natW/natH>ratio){h=natH*pct;w=h*ratio;}else{w=natW*pct;h=w/ratio;}
   }else{w=natW*pct;h=natH*pct;}
   cp.w=w;cp.h=h;cp.x=(natW-w)/2;cp.y=(natH-h)/2;
   clampAll(ratio);paintBox();
  }
  function load(f){
   msg.innerHTML='';panel.hidden=true;img=null;
   if(!f){return;}
   if(!/^image\/(jpeg|png|webp)$/.test(f.type)){msg.innerHTML='<div class="msg err">Please choose a JPG, PNG or WebP image.</div>';return;}
   if(f.size>50*1048576){msg.innerHTML='<div class="msg err">This file is larger than 50 MB. Please choose a smaller image.</div>';return;}
   revoke();name=f.name.replace(/\.[^.]+$/,'')||'image';srcUrl=URL.createObjectURL(f);
   var im=new Image();
   im.onload=function(){
    img=im;natW=im.naturalWidth;natH=im.naturalHeight;
    imgEl.src=srcUrl;panel.hidden=false;
    requestAnimationFrame(function(){centerBox(0.7);});
   };
   im.onerror=function(){msg.innerHTML='<div class="msg err">This image could not be read. It may be damaged or in an unsupported format.</div>';};
   im.src=srcUrl;
  }
  function onResize(){if(natW){paintBox();}}
  window.addEventListener('resize',onResize);
  TH.onLeave(function(){window.removeEventListener('resize',onResize);revoke();});

  var dragging=false,startPX=0,startPY=0,startX=0,startY=0;
  box.addEventListener('pointerdown',function(e){
   dragging=true;startPX=e.clientX;startPY=e.clientY;startX=cp.x;startY=cp.y;
   try{box.setPointerCapture(e.pointerId);}catch(e2){}
   e.preventDefault();
  });
  box.addEventListener('pointermove',function(e){
