   cp.x=startX+(e.clientX-startPX)/s;cp.y=startY+(e.clientY-startPY)/s;
   cp.x=Math.max(0,Math.min(cp.x,natW-cp.w));cp.y=Math.max(0,Math.min(cp.y,natH-cp.h));
   paintBox();
  });
  function endDrag(){dragging=false;}
  box.addEventListener('pointerup',endDrag);
  box.addEventListener('pointercancel',endDrag);

  ratioSel.addEventListener('change',function(){clampAll(ratioValue());paintBox();});
  wI2.addEventListener('input',function(){cp.w=Math.max(1,+wI2.value||1);var r=ratioValue();if(r){cp.h=cp.w/r;}clampAll(r);paintBox();});
  hI2.addEventListener('input',function(){cp.h=Math.max(1,+hI2.value||1);var r=ratioValue();if(r){cp.w=cp.h*r;}clampAll(r);paintBox();});
  xI.addEventListener('input',function(){cp.x=+xI.value||0;clampAll(ratioValue());paintBox();});
  yI.addEventListener('input',function(){cp.y=+yI.value||0;clampAll(ratioValue());paintBox();});
  $('#cp2-center',root).addEventListener('click',function(){if(natW){centerBox(0.7);}});

  drop.addEventListener('click',function(){file.click();});
  drop.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();file.click();}});
  file.addEventListener('change',function(){load(file.files[0]);file.value='';});
  ['dragenter','dragover'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.add('over');});});
  ['dragleave','drop'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.remove('over');});});
  drop.addEventListener('drop',function(e){load(e.dataTransfer&&e.dataTransfer.files[0]);});
  $('#cp2-new',root).addEventListener('click',function(){file.click();});

  $('#cp2-go',root).addEventListener('click',function(){
   if(!img){return;}
   clampAll(ratioValue());
   var x=Math.round(cp.x),y=Math.round(cp.y),w=Math.round(cp.w),h=Math.round(cp.h);
   if(w<1||h<1){msg.innerHTML='<div class="msg err">Please choose a crop area first.</div>';return;}
   var cv=document.createElement('canvas');cv.width=w;cv.height=h;
   var ctx=cv.getContext('2d');
   if(fmtSel2.value==='image/jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);}
   ctx.drawImage(img,x,y,w,h,0,0,w,h);
   cv.toBlob(function(b){
    if(!b){msg.innerHTML='<div class="msg err">Cropping failed in this browser. Try a different output format.</div>';return;}
    var ext=b.type==='image/png'?'png':(b.type==='image/webp'?'webp':'jpg');
    TH.saveBlob(b,name+'-cropped.'+ext);
    msg.innerHTML='<div class="msg ok">Cropped to '+w+'\u00D7'+h+' px. Your download has started.</div>';
   },fmtSel2.value,0.92);
  });
 },
