 short:'Paste a list and instantly remove repeated lines, with optional case-insensitive matching.',
 kw:'remove duplicate lines duplicate line remover unique lines list cleaner dedupe text',
 title:'Remove Duplicate Lines Online Free',
 desc:'Free online tool to remove duplicate lines from a list or block of text. Case-insensitive and whitespace-trim options included. Runs in your browser; nothing is uploaded.',
 render:function(root){
  root.innerHTML=
   '<div class="field"><label for="dl-in">Your text</label><textarea id="dl-in" placeholder="Paste a list of lines, one per line..."></textarea></div>'
   +'<div class="btn-row" style="margin-top:0">'
   +'<label class="chk"><input type="checkbox" id="dl-ci"> Case-insensitive</label>'
   +'<label class="chk"><input type="checkbox" id="dl-trim" checked> Trim whitespace</label>'
   +'<label class="chk"><input type="checkbox" id="dl-empty"> Remove empty lines</label></div>'
   +'<div class="btn-row"><button class="btn btn-primary" type="button" id="dl-go">'+icon('check')+'Remove duplicates</button></div>'
   +'<div id="dl-msg"></div>'
   +'<div class="field"><label for="dl-out">Result</label><textarea id="dl-out" readonly placeholder="Your cleaned list appears here"></textarea></div>'
   +'<div class="btn-row" style="margin-top:0">'
   +'<button class="btn btn-primary" type="button" id="dl-copy">'+icon('copy')+'Copy result</button>'
   +'<button class="btn" type="button" id="dl-dl">'+icon('download')+'Download .txt</button>'
   +'<button class="btn" type="button" id="dl-clear">'+icon('trash')+'Clear</button></div>';
  var inp=$('#dl-in',root),out=$('#dl-out',root),msg=$('#dl-msg',root);
  var ci=$('#dl-ci',root),trim=$('#dl-trim',root),noEmpty=$('#dl-empty',root);
  function run(){
   if(!inp.value){msg.innerHTML='<div class="msg err">Paste some text first.</div>';return;}
   var lines=inp.value.split(/\r\n|\r|\n/),seen={},kept=[];
   lines.forEach(function(line){
    var v=trim.checked?line.trim():line;
    if(noEmpty.checked&&v.trim()===''){return;}
    var key=ci.checked?v.toLowerCase():v;
    if(Object.prototype.hasOwnProperty.call(seen,key)){return;}
    seen[key]=1;kept.push(v);
   });
   out.value=kept.join('\n');
   var removed=lines.length-kept.length;
   msg.innerHTML='<div class="msg ok">'+lines.length+' line'+(lines.length===1?'':'s')+' in, '+kept.length+' kept, '+removed+' duplicate'+(removed===1?'':'s')+' removed.</div>';
  }
  $('#dl-go',root).addEventListener('click',run);
  $('#dl-copy',root).addEventListener('click',function(){if(!out.value){TH.toast('Remove duplicates first');return;}TH.copy(out.value,'Result copied');});
  $('#dl-dl',root).addEventListener('click',function(){if(!out.value){TH.toast('Nothing to download yet');return;}TH.saveBlob(new Blob([out.value],{type:'text/plain;charset=utf-8'}),'unique-lines.txt');});
