TH.add({
 slug:'sort-text-lines',name:'Text Sorter',h1:'Sort Lines of Text',cat:'Text',icon:'list',
 short:'Sort a list alphabetically, by length or numerically, with optional dedupe.',
 kw:'sort text lines alphabetical sort text sorter sort list a-z z-a numeric sort',
 title:'Text Sorter: Sort Lines Alphabetically, by Length or Numerically',
 desc:'Free online text sorter. Sort lines A-Z, Z-A, by length or numerically, with options to remove empty lines and duplicates. Runs in your browser.',
 render:function(root){
  root.innerHTML=
   '<div class="field"><label for="ts-in">Your text</label><textarea id="ts-in" placeholder="Paste a list of lines, one per line..."></textarea></div>'
   +'<div class="btn-row" style="margin-top:0">'
   +'<label class="chk"><input type="checkbox" id="ts-ci"> Case-insensitive</label>'
   +'<label class="chk"><input type="checkbox" id="ts-empty"> Remove empty lines</label>'
