   +'<div class="case-grid" role="group" aria-label="Choose a sort order">'
   +'<button class="btn" type="button" data-m="az">A &rarr; Z</button>'
   +'<button class="btn" type="button" data-m="za">Z &rarr; A</button>'
   +'<button class="btn" type="button" data-m="shortlong">Shortest first</button>'
   +'<button class="btn" type="button" data-m="longshort">Longest first</button>'
   +'<button class="btn" type="button" data-m="numeric">Numeric</button>'
   +'<button class="btn" type="button" data-m="reverse">Reverse order</button></div>'
   +'<div id="ts-msg"></div>'
   +'<div class="field"><label for="ts-out">Result</label><textarea id="ts-out" readonly placeholder="Your sorted list appears here"></textarea></div>'
   +'<div class="btn-row" style="margin-top:0">'
   +'<button class="btn btn-primary" type="button" id="ts-copy">'+icon('copy')+'Copy result</button>'
   +'<button class="btn" type="button" id="ts-dl">'+icon('download')+'Download .txt</button>'
   +'<button class="btn" type="button" id="ts-clear">'+icon('trash')+'Clear</button></div>';
  var inp=$('#ts-in',root),out=$('#ts-out',root),msg=$('#ts-msg',root);
  var ci=$('#ts-ci',root),noEmpty=$('#ts-empty',root),dedupe=$('#ts-dedupe',root);
  function cmpText(a,b,useCi){var x=useCi?a.toLowerCase():a,y=useCi?b.toLowerCase():b;return x<y?-1:x>y?1:0;}
  function run(mode){
   if(!inp.value){msg.innerHTML='<div class="msg err">Paste some text first.</div>';return;}
   var useCi=ci.checked;
   var lines=inp.value.split(/\r\n|\r|\n/);
   if(noEmpty.checked){lines=lines.filter(function(l){return l.trim()!=='';});}
   var arr=lines.slice();
   if(mode==='az'){arr.sort(function(a,b){return cmpText(a,b,useCi);});}
   else if(mode==='za'){arr.sort(function(a,b){return cmpText(a,b,useCi);}).reverse();}
   else if(mode==='shortlong'){arr.sort(function(a,b){return a.length-b.length||cmpText(a,b,useCi);});}
   else if(mode==='longshort'){arr.sort(function(a,b){return b.length-a.length||cmpText(a,b,useCi);});}
   else if(mode==='numeric'){arr.sort(function(a,b){return (parseFloat(a)||0)-(parseFloat(b)||0);});}
   else if(mode==='reverse'){arr.reverse();}
   if(dedupe.checked){
    var seen={};arr=arr.filter(function(l){var k=useCi?l.toLowerCase():l;if(seen[k]){return false;}seen[k]=1;return true;});
   }
   out.value=arr.join('\n');
   msg.innerHTML='<div class="msg ok">'+arr.length+' line'+(arr.length===1?'':'s')+' in the result.</div>';
  }
  $$('.case-grid .btn',root).forEach(function(b){b.addEventListener('click',function(){run(b.getAttribute('data-m'));});});
  $('#ts-copy',root).addEventListener('click',function(){if(!out.value){TH.toast('Sort your text first');return;}TH.copy(out.value,'Result copied');});
  $('#ts-dl',root).addEventListener('click',function(){if(!out.value){TH.toast('Nothing to download yet');return;}TH.saveBlob(new Blob([out.value],{type:'text/plain;charset=utf-8'}),'sorted-lines.txt');});
  $('#ts-clear',root).addEventListener('click',function(){inp.value='';out.value='';msg.innerHTML='';inp.focus();});
