   +'<button class="btn" type="button" id="rn-dl">'+icon('download')+'Download .txt</button></div>';
  var minI=$('#rn-min',root),maxI=$('#rn-max',root),countI=$('#rn-count',root),placesWrap=$('#rn-places-wrap',root),placesI=$('#rn-places',root);
  var wholeChk=$('#rn-whole',root),uniqueChk=$('#rn-unique',root),msg=$('#rn-msg',root),out=$('#rn-out',root);
  function toggleWhole(){placesWrap.hidden=wholeChk.checked;}
  wholeChk.addEventListener('change',toggleWhole);
  function randInt(min,max){return Math.floor(Math.random()*(max-min+1))+min;}
  $('#rn-go',root).addEventListener('click',function(){
