   if(isNaN(min)||isNaN(max)){msg.innerHTML='<div class="msg err">Please enter valid minimum and maximum values.</div>';return;}
   if(min>max){var t=min;min=max;max=t;}
   var count=Math.round(+countI.value)||0;
   if(count<1){msg.innerHTML='<div class="msg err">Enter how many numbers to generate (at least 1).</div>';return;}
   if(count>10000){msg.innerHTML='<div class="msg err">Maximum is 10,000 numbers at once.</div>';return;}
   var unique=uniqueChk.checked,results;
   if(wholeChk.checked){
    if(unique){
     var rangeSize=Math.floor(max)-Math.ceil(min)+1;
     if(count>rangeSize){msg.innerHTML='<div class="msg err">Cannot generate '+count+' unique whole numbers between '+min+' and '+max+' &mdash; only '+rangeSize+' possible value'+(rangeSize===1?'':'s')+' exist'+(rangeSize===1?'s':'')+' in that range.</div>';return;}
     var set={},arr=[];
     while(arr.length<count){var v=randInt(min,max);if(!set[v]){set[v]=1;arr.push(v);}}
     results=arr;
    }else{
     results=[];for(var i=0;i<count;i++){results.push(randInt(min,max));}
    }
   }else{
    var places=Math.max(0,Math.min(10,Math.round(+placesI.value)||0));
    var seen=unique?{}:null,arr2=[],tries=0,maxTries=count*200+1000;
    while(arr2.length<count&&tries<maxTries){
     tries++;
     var val=+(Math.random()*(max-min)+min).toFixed(places);
     if(unique){if(seen[val]){continue;}seen[val]=1;}
     arr2.push(val);
    }
    if(arr2.length<count){msg.innerHTML='<div class="msg err">Could not generate that many unique decimal values in this range. Try allowing duplicates, more decimal places, or a wider range.</div>';return;}
    results=arr2;
   }
   out.value=results.join(', ');
   msg.innerHTML='<div class="msg ok">Generated '+results.length+' number'+(results.length===1?'':'s')+'.</div>';
  });
  $('#rn-copy',root).addEventListener('click',function(){if(!out.value){TH.toast('Generate numbers first');return;}TH.copy(out.value,'Numbers copied');});
  $('#rn-dl',root).addEventListener('click',function(){if(!out.value){TH.toast('Nothing to download yet');return;}TH.saveBlob(new Blob([out.value],{type:'text/plain;charset=utf-8'}),'random-numbers.txt');});
 },
