TH.add({
 slug:'file-info',name:'File Info Checker',h1:'File Info & MIME Type Checker',cat:'PDF & Files',icon:'info',
 short:'Check a file\u2019s type, extension, exact size and last-modified date before you use it.',
 kw:'file info checker mime type checker file type detector file size checker file details',
 title:'File Info Checker: MIME Type, Size & Details Online',
 desc:'Free online tool to check a file\u2019s MIME type, extension, exact size and last-modified date. Files are read locally in your browser and never uploaded.',
 render:function(root){
  root.innerHTML=
   '<div class="drop" id="fi-drop" tabindex="0" role="button" aria-label="Choose files to inspect">'+icon('upload')+'<p style="margin:0"><strong>Click to choose files</strong> or drag and drop them here</p><p class="hint" style="margin:6px 0 0">Any file type. Only basic details are read; files are never uploaded.</p></div>'
   +'<input type="file" id="fi-file" multiple hidden>'
   +'<div id="fi-msg"></div>'
   +'<div id="fi-list" class="flist"></div>'
   +'<div class="btn-row" id="fi-actions" hidden>'
   +'<button class="btn btn-primary" type="button" id="fi-copy">'+icon('copy')+'Copy details</button>'
   +'<button class="btn" type="button" id="fi-clear">'+icon('trash')+'Clear</button></div>';
  var drop=$('#fi-drop',root),file=$('#fi-file',root),msg=$('#fi-msg',root),listEl=$('#fi-list',root),actions=$('#fi-actions',root);
  var items=[];
  function extOf(name){var m=/\.([a-z0-9]+)$/i.exec(name);return m?m[1].toLowerCase():'none';}
  function line(f){return TH.esc(f.name)+' \u00B7 '+TH.esc(f.type||'unknown type')+' \u00B7 .'+TH.esc(extOf(f.name))+' \u00B7 '+TH.bytes(f.size)+' ('+f.size.toLocaleString()+' bytes) \u00B7 modified '+TH.esc(new Date(f.lastModified).toLocaleString());}
  function paint(){
   actions.hidden=!items.length;
   listEl.innerHTML=items.map(function(f){
    return '<div class="frow" style="align-items:flex-start">'+icon('file')
     +'<span class="fname" style="white-space:normal;flex:1">'+line(f)+'</span></div>';
   }).join('');
  }
  function addFiles(list0){
   msg.innerHTML='';
   Array.prototype.slice.call(list0).forEach(function(f){items.push(f);});
   paint();
  }
  drop.addEventListener('click',function(){file.click();});
  drop.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();file.click();}});
  file.addEventListener('change',function(){addFiles(file.files);file.value='';});
  ['dragenter','dragover'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.add('over');});});
  ['dragleave','drop'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.remove('over');});});
  drop.addEventListener('drop',function(e){var f=e.dataTransfer&&e.dataTransfer.files;if(f&&f.length){addFiles(f);}});
  $('#fi-clear',root).addEventListener('click',function(){items=[];paint();msg.innerHTML='';});
  $('#fi-copy',root).addEventListener('click',function(){
   if(!items.length){TH.toast('Choose a file first');return;}
   var txt=items.map(function(f){return f.name+' | '+(f.type||'unknown')+' | .'+extOf(f.name)+' | '+f.size+' bytes ('+TH.bytes(f.size)+') | modified '+new Date(f.lastModified).toLocaleString();}).join('\n');
   TH.copy(txt,'File details copied');
  });
 },
 art:{
  intro:[
   'The File Info Checker reads a file&rsquo;s basic details directly in your browser: its detected MIME type, file extension, exact size in bytes, and when it was last modified. This is useful for confirming a file is what it claims to be before uploading it somewhere, or for checking exact byte sizes against a limit.',
   'The file itself is never uploaded or read beyond these details; only the browser&rsquo;s built-in file metadata is used.'
