/* =====================================================================
   TOOL 22: TEXT CLEANER
   Whitespace, blank-line and punctuation normalization. Logic verified
   with standalone unit tests before being written here.
   ===================================================================== */
(function(TH){try{
var $=TH.$,$$=TH.$$,icon=TH.icon;

TH.add({
 slug:'text-cleaner',name:'Text Cleaner',h1:'Text Cleaner',cat:'Text',icon:'zap',
 short:'Trim extra spaces, collapse blank lines, strip HTML tags and straighten smart quotes in one click.',
 kw:'text cleaner remove extra spaces clean text whitespace remover strip html straighten smart quotes',
 title:'Text Cleaner: Remove Extra Spaces & Fix Formatting Online',
 desc:'Free online text cleaner. Trim whitespace, collapse blank lines, strip HTML tags and straighten curly quotes and dashes. Runs in your browser; nothing is uploaded.',
 render:function(root){
  root.innerHTML=
   '<div class="field"><label for="tc-in">Your text</label><textarea id="tc-in" placeholder="Paste messy text, pasted-from-web content or copy with extra spacing..."></textarea></div>'
   +'<div class="btn-row" style="margin-top:0;flex-wrap:wrap">'
   +'<label class="chk"><input type="checkbox" id="tc-trim" checked> Trim each line</label>'
   +'<label class="chk"><input type="checkbox" id="tc-collapse" checked> Collapse extra spaces</label>'
   +'<label class="chk"><input type="checkbox" id="tc-blank" checked> Collapse blank lines</label>'
   +'<label class="chk"><input type="checkbox" id="tc-quotes" checked> Straighten quotes &amp; dashes</label>'
   +'<label class="chk"><input type="checkbox" id="tc-html"> Strip HTML tags</label>'
   +'<label class="chk"><input type="checkbox" id="tc-join"> Join into one paragraph</label></div>'
   +'<div class="btn-row"><button class="btn btn-primary" type="button" id="tc-go">'+icon('check')+'Clean text</button></div>'
   +'<div id="tc-msg"></div>'
   +'<div class="field"><label for="tc-out">Result</label><textarea id="tc-out" readonly placeholder="Your cleaned text appears here"></textarea></div>'
   +'<div class="btn-row" style="margin-top:0">'
   +'<button class="btn btn-primary" type="button" id="tc-copy">'+icon('copy')+'Copy result</button>'
   +'<button class="btn" type="button" id="tc-dl">'+icon('download')+'Download .txt</button>'
   +'<button class="btn" type="button" id="tc-clear">'+icon('trash')+'Clear</button></div>';
  var inp=$('#tc-in',root),out=$('#tc-out',root),msg=$('#tc-msg',root);
  var trimChk=$('#tc-trim',root),collapseChk=$('#tc-collapse',root),blankChk=$('#tc-blank',root),quotesChk=$('#tc-quotes',root),htmlChk=$('#tc-html',root),joinChk=$('#tc-join',root);
  function straighten(s){
   return s
    .replace(/[\u2018\u2019\u201A\u201B]/g,"'")
    .replace(/[\u201C\u201D\u201E\u201F]/g,'"')
    .replace(/[\u2013\u2014]/g,'-')
    .replace(/\u2026/g,'...');
  }
  function run(){
   if(!inp.value){msg.innerHTML='<div class="msg err">Paste some text first.</div>';return;}
   var before=inp.value.length,s=inp.value;
   if(htmlChk.checked){s=TH.strip(s);}
   if(quotesChk.checked){s=straighten(s);}
   var lines=s.split(/\r\n|\r|\n/);
   if(trimChk.checked){lines=lines.map(function(l){return l.trim();});}
   if(collapseChk.checked){lines=lines.map(function(l){return l.replace(/[ \t]+/g,' ');});}
   var result;
   if(joinChk.checked){
    result=lines.filter(function(l){return l!=='';}).join(' ');
    if(collapseChk.checked){result=result.replace(/ +/g,' ');}
   }else{
    if(blankChk.checked){
     var cleaned=[],prevBlank=false;
     lines.forEach(function(l){
      var isBlank=l.trim()==='';
      if(isBlank&&prevBlank){return;}
      cleaned.push(l);prevBlank=isBlank;
     });
     lines=cleaned;
    }
    result=lines.join('\n');
   }
   out.value=result;
   msg.innerHTML='<div class="msg ok">Cleaned. '+before.toLocaleString()+' characters in, '+result.length.toLocaleString()+' characters out.</div>';
  }
  $('#tc-go',root).addEventListener('click',run);
  $('#tc-copy',root).addEventListener('click',function(){if(!out.value){TH.toast('Clean your text first');return;}TH.copy(out.value,'Result copied');});
  $('#tc-dl',root).addEventListener('click',function(){if(!out.value){TH.toast('Nothing to download yet');return;}TH.saveBlob(new Blob([out.value],{type:'text/plain;charset=utf-8'}),'cleaned-text.txt');});
  $('#tc-clear',root).addEventListener('click',function(){inp.value='';out.value='';msg.innerHTML='';inp.focus();});
 },
 art:{
